// ======================================================================
// Build stamp. Shown on the sign-in screen and in the footer so you can
// tell at a glance whether the deployed site is the version you pushed —
// GitHub Pages and the browser cache can both lag a commit behind.
//
// `build` matches the ?v= cache-busting number on every asset URL in
// index.html; bump both together when releasing.
// ======================================================================
const APP_BUILD = {
  version: "1.0",
  // Two number series, one per channel. Production builds are plain integers
  // (…, 226, 227) on main. Beta-channel builds are five digits, NNNII — NNN
  // the cycle, II the iteration — so 22701 renders as v1.0.227-beta.1 and can
  // never collide with a production number. On release: merge beta into main,
  // set build to a production integer, and consolidate the cycle's changelog
  // entries into one entry. The What's-new overlay compares numerically per
  // origin, and both series are monotone on their own origin.
  //
  // `cycle` IS NOT DERIVED FROM `build`, and that is the whole point. It used
  // to be — Math.floor(build / 100) — which silently rolled over the moment a
  // cycle passed its 99th iteration: 25100 rendered as v1.0.251-beta.0, so
  // from build 25100 to 25112 the sign-in screen announced a beta of v1.0.251,
  // a production build that had already shipped 30 releases earlier. Stating
  // the cycle outright makes the iteration count unbounded (beta.112, beta.250,
  // as far as a cycle runs) and the rollover impossible. Set it once per cycle,
  // when the first beta build after a production release is cut.
  //
  // A note on what `cycle` means now: it was originally read as "the production
  // build this cycle will become", which stopped being true once items began
  // graduating to production one queue number at a time — production walked
  // 250 → 281 while this cycle stayed 250. It is a cycle NAME, not a promise.
  cycle: 250,
  build: 25492,
  date: "2026-09-22",
  // When this build was cut, UTC — set it with `date -u +%Y-%m-%dT%H:%MZ`,
  // never by hand. Builds 25090-25092 and 277 carried a local Amsterdam time
  // in this field, so the sign-in stamp read over an hour into the future:
  // typing a local time into a field labelled UTC is the same mistake the
  // local-time display exists to stop somebody making.
  // Shown on the sign-in screen with the version:
  // the date alone cannot tell two releases of the same day apart, and "is the
  // thing I just pushed actually live?" is a question about minutes, not days.
  released: "2026-09-23T11:43Z",
  get isBeta() { return this.build >= 10000; },
  // Stored UTC, shown in the reader's own timezone with the offset named.
  // A build is cut once, so one absolute instant is the right thing to record —
  // but "when was this last updated?" is asked by somebody sitting in a
  // timezone, and an ISO Z stamp makes every one of them do the arithmetic.
  // The UTC original stays reachable in the element's tooltip.
  get stamp() { return `${this.label} · ${this.releasedLocal}`; },
  get releasedLocal() {
    const raw = String(this.released || "");
    const d = new Date(raw);
    if (isNaN(d.getTime())) return raw.replace("T", " ");    // unparseable — show it raw rather than "Invalid Date"
    try {
      const parts = new Intl.DateTimeFormat(undefined, {
        year: "numeric", month: "2-digit", day: "2-digit",
        hour: "2-digit", minute: "2-digit", hourCycle: "h23", timeZoneName: "short",
      }).formatToParts(d);
      const g = (t) => (parts.find((x) => x.type === t) || {}).value || "";
      if (!g("year")) return raw.replace("T", " ");
      const zone = g("timeZoneName");
      return `${g("year")}-${g("month")}-${g("day")} ${g("hour")}:${g("minute")}${zone ? ` ${zone}` : ""}`;
    } catch { return raw.replace("T", " "); }                 // Intl is optional in principle
  },
  get releasedUtc() { return String(this.released || "").replace("T", " ").replace("Z", " UTC"); },
  get timeZone() { try { return Intl.DateTimeFormat().resolvedOptions().timeZone || ""; } catch { return ""; } },
  // The iteration is whatever is left above the cycle's base, so it keeps
  // counting past 99 instead of wrapping into the next hundred. `cycle` is
  // missing on nothing that ships, but fall back to the old division rather
  // than print NaN if it ever is.
  get iteration() {
    return this.cycle ? this.build - this.cycle * 100 : this.build % 100;
  },
  get label() {
    return this.isBeta
      ? `v${this.version}.${this.cycle || Math.floor(this.build / 100)}-beta.${this.iteration}`
      : `v${this.version}.${this.build}`;
  },
  get full() { return `${this.label} · ${this.date}`; },
};

// Per-tool versions, keyed by the tile id in index.html. Each tool moves at
// its own pace, so a tenant-side reviewer can tell which one changed since
// they last looked without diffing the whole app. Bump the tool you touched.
//
// A tool that has reached PRODUCTION is at least 1.0. Whatever it accumulated
// on the beta channel, something a customer can open is not a 0.x thing — and
// it is the BETA chip, not the version number, that says "still proving
// itself". Only beta-channel-only tools stay below 1.0.
//
// ── `t` — THE TOOL'S PERMANENT NUMBER (roadmap R33) ────────────────────
//
// The roadmap items carry Rnn references so one can be pointed at without
// quoting its title. The tools went by name and emoji, which drift: tools get
// renamed, retitled and — once R26 lands — translated, so "the group tool" is
// already ambiguous and a Dutch interface would make every English note about
// a tool unfindable. `t` is the same discipline for the tools themselves.
//
// THE RULES, and they are the whole value of the number:
//
//   * Assigned in the ORDER THE TOOL ENTERED ENCA. T01–T31 were reconstructed
//     from git — the first commit that put each tile in index.html, ordered by
//     commit time, with tools that arrived in one commit ordered as they were
//     written into the page. That is a fact about the repository, not a
//     judgement, so it can be checked rather than argued about.
//   * NEVER REUSED. Not when a tool is retired, not when it is folded into
//     another. A recycled number makes every older note about it wrong, which
//     is precisely the failure the number exists to prevent.
//   * A NEW TOOL TAKES THE NEXT FREE NUMBER — 40 next — and takes it in the
//     same commit that adds the tile, like the changelog entry and the
//     promotion-queue row.
//
// WHAT IS DELIBERATELY NOT NUMBERED: ❓ Help, 📋 What's new and 🗺 Roadmap.
// They are the app describing itself rather than tools that read a tenant,
// produce a report about it or write to it — which is also why they carry no
// version. They go by name, and that is stated rather than left as a gap
// somebody later "fixes" by giving them numbers and shifting everything.
//
// The entries below are ordered by where a tool sits on the home page, not by
// its number: `t` is the record of age, this object's order is not, and the
// two are allowed to disagree.
const TOOL_VERSIONS = {
  toolDeploy: { t: 40, v: "1.2.1", note: "25374: rollout selection displays full original policy names with wrapping and no generated aliases or duplicate subtitles. 25369: streamed coverage transfers and global result ordering; local acceptance and live read-only evidence recorded. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. CloudFellows policies from a backup ZIP; Joey policies from Fetch latest, including dependencies and release provenance. Guided rollout: scope, backup and import plan, observed impact, then reviewed policy state. Uses existing confirmations; acknowledgements are manual and session-only." },
  toolBuilder:      { t: 41, v: "0.4.1", head: "\ud83c\udfd7 Policy builder", chips: ["BETA", "writes to tenant"], folded: { into: "toolLocations", build: 25437 }, note: "0.4.1 (25479, Mihai: the checks used to check also on OR — where is that now?): THE OR JUDGEMENT WHERE THE CHOICE IS MADE. Builder.hints gives step 5 the same verdict 🛡 Checks → Bypass & Swiss cheese gives after the fact (gapcheck checkOr since 25470): management controls only — info, same tier; MFA or a strength OR a compliant / hybrid-joined device — info, Microsoft's template, with what AND would cost; MFA OR app protection or password change — warn, reported as Medium; anything OR terms of use — warn, reported as High; OR across controls none of which is a second factor — warn. And the CARD EDIT now shows the builder's hints under the box they are about (Users, Target resources, Conditions, Grant, Session) — it showed none, so a break-glass group left out or an OR that skips MFA passed there without a word while the builder flagged it. 0.4.0 (25478, Mihai with two screenshots: after save the screen returns to the one policy filtered — to continue I have to clear the filter, filter the persona again, go to the policy to edit; and: at service provider no option to only add one or more service providers). BACK WHERE YOU WERE: a builder save set idFilter to the one saved policy and reset the state filter, and with a pool of one the persona chip bar hides itself and CLEARS the persona filter, so every edit cost three clicks to get back. Now the list returns as it was left — persona, state, search — with the saved policy open in the inspector; only when those filters would hide it (a new policy outside the persona you picked) is the list narrowed to it. The card edit already kept the filters and still does. CHOSEN TENANTS: the guest panel of both surfaces has External tenants — All external tenants, or Only the tenants I choose — with the cross-tenant partners configured in the tenant as one-click picks (service providers first, marked 🤝, from Graph.crossTenantTrust) and a box for any other tenant ID (GUIDs only). It says outright that Entra keeps ONE tenant list per clause, so the choice covers every type ticked there, and what to do if only Service provider users should be limited. Ticking a type no longer resets the clause to all tenants (pbToggle kept only the types). validate() refuses an enumerated clause with no tenant rather than let Graph 400 or widen it. One test in tools/builder.test.cjs; the whole flow driven in the demo. 0.3.3 (25465, Mihai: in the entra portal, its not possible when selecting, its one or the other): THE PAIR IS REFUSED WHERE THE CHOICE IS MADE. The portal greys out Require multifactor authentication while an authentication strength is selected and says why; nothing here stopped you ticking both, and the pair was only found out at the save, by Graph, as a bare 400 naming no field. validate() now blocks it with Entra own wording and says how to resolve it — pick the strength, or pick the control and set the strength to none — so Save is disabled before the round-trip rather than after it. Block policies are unaffected. A standing test had built its own valid draft out of that very pair to exercise the AND/OR rule and was corrected to two built-in controls. 0.3.2 (25464, Mihai: yes I am trying to change the Authentication strength to mfa): TAKING A STRENGTH OFF NEEDS AN EXPLICIT NULL. toRaw omits authenticationStrength when no strength is chosen, and a PATCH that OMITS the key leaves the strength in place — so the policy was asked to hold a strength AND Require multifactor authentication at once, which Entra refuses outright, and the save came back a bare 400 BadRequest naming no field. patchBody now writes authenticationStrength: null when the policy had one and the draft does not, and only then. It is exactly the swap the 25459 MS Learn check recommends, so the tool was failing at the step its own advice leads to. HARDENING in the same build: the guest clause was the one part of conditions carried through from the read rather than rebuilt, so whatever Graph returned went back verbatim — guestClause() now names the externalTenants derived type on every write (#…AllExternalTenants / #…EnumeratedExternalTenants; an enumerated clause stays enumerated even with no members, because falling back to all would widen a policy from three partner tenants to every tenant on earth) and drops read annotations. Six tests in tools/builder.test.cjs. 0.3.1 (25457, Mihai: when clicking one it collapses again, so I need to expand again to select another): A FOLD THE PERSON OPENED STAYS OPEN. Every tick inside a pb-det panel goes through pbOnChange to pbRepaint, which rewrites the whole step from the draft — and markup written without the open attribute comes back CLOSED, so ticking one guest type folded the panel and the second type meant opening it again. pbDet(key, summary, body) writes open from a pbDets set, and a CAPTURE-phase toggle listener on both surfaces records what the person opens (toggle does not bubble). Four panels were wrong the same way, not just the guest one: include guests, exclude guests, exclude selected locations, exclude platforms — each its own key, so the include and exclude sides fold independently. The open set is deliberately NOT in the draft: it is what the person is looking at, not part of the policy. 0.3.0 (25456, Mihai: editing a policy should be edit and not replace with a clone): THE 🗂 START OFFERS BOTH VERBS AGAIN. Since 25448 the Start-from-a-policy picker offered ⧉ Clone alone and told the reader to go to the card instead, so picking the policy you meant to CHANGE handed you a new one at the next free number — a clone is not an edit, and a picker that answers a question you did not ask is a trap. Every row now carries ✎ Edit this policy (that policy itself: its number, its name and its state kept, Save writing only the sections that differ) beside ⧉ Clone into a new policy, and the line above says which is which. Only the entry point comes back — edit mode itself never left: the draft mode, the before-state, the Diff view and the whole-section PATCH have been there since 25445. 0.2.1 (25454): the split handle between the steps and the preview works — it was the shared frame's slider, copied in unwired. 0.2.0 (25446, Mihai: editing a policy is not creating a new one): AN EDIT LOOKS LIKE AN EDIT — the toolbar shows Editing <name> with Discard instead of the Start-from segment, the head says nothing is written until Save, every step reads as filled in, step 1 is the name (the convention fields only for a convention name, the persona fixed — Clone is for a new number), step 7 is State and save with the number of settings that change and Save disabled while nothing does. 0.1.1 (25441, Mihai: the select items box must match the site): the persona chips are the site's filter chips (fchip, lemon when active) — they carried a class that does not exist and rendered as bare buttons with no visible choice. 0.1.0 (25437, R23 built on R17): BETA. One guided screen for a policy, the sixth tab of T15 Policy building blocks because a policy IS what the other five tabs are blocks of. Seven steps (name and persona, who, what, when, then, session, state) with the tenant's named locations, authentication contexts, strengths and terms of use as pickers; the name follows the CAnnn-KIND-Persona-words-vX.Y convention with the next free number in the persona's range; best-practice hints computed over the loaded policies (break-glass not excluded, legacy auth already blocked tenant-wide, IP locations not marked trusted behind All trusted, empty country locations, overlap with enabled policies); preflight through WhatIfEval with synthetic subjects; Card, JSON, Preflight and Diff previews; Change plan export (R22). Three starts: blank, a baseline template (the live counterpart when the tenant holds that number, else the template's structured half plus its own words), or a policy selected elsewhere: Open in builder on the Policies action bar edits it (PATCH of WHOLE sections, only the changed ones, read back with the import settle schedule) or clones it (next free number, report-only); New policy with this location / strength / context / terms on the four block panes pre-fills that step. A new policy is born report-only; On needs a typed ON; the optional exclusion group is created FIRST so the policy never names a group that failed to exist. js/builder.js is pure and tested (tools/builder.test.cjs)" },
  toolMemberOf:     { t: 34, v: "1.1", head: "\ud83e\uddf7 memberOf retirement", chips: ["BETA", { txt: "\u23f3 temporary tool", title: "This tool exists for one dated retirement and is removed once the date has passed" }, "reads only"], note: "25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. 1.0: in production as build 304 — the version says a customer can open it, and the BETA chip stays while it proves itself against real tenants. 0.2: the THIRD surface is read too — entitlement-management auto-assignment policies, which 0.1 named as a gap and pointed elsewhere for. It is the hardest of the three to look at by hand, because the rule sits in specificAllowedTargets on a policy inside an access package inside a catalog and no view in the portal lists them across the tenant. Read through the same candidate ladder js/groupuse.js uses, since the relationship name moved between beta and v1.0 and ENCA runs on beta; the line is drawn where Microsoft's own script draws it, keeping only policies that carry automaticRequestSettings, because a request-based policy has no rule to freeze. Severity comes from requestAccessForAllowedTargets: a policy handing out an access package TODAY is critical, one defined but not assigning is high, and removeAccessWhenTargetLeavesAllowedTargets is called out separately because it is the quiet half — with the rule frozen nobody ever leaves the scope, so revocation stops happening while the setting still reads as on. Needs EntitlementManagement.Read.All, asked once on the run click and degrading to NOT READ when declined, and a new allSurfaces fact drives a genuinely different clean verdict: all three read means nothing to migrate, two of three means not a clean tenant yet, said in those words on screen and in the report. 0.1: TEMPORARY tool — the memberOf dynamic rule operator has been in public preview since 2022 and Microsoft ends that preview on 3 November 2026. Rules using it do NOT fail on that date: they stop updating and stay in their last known state, so a frozen group keeps handing out whatever membership it held that day, joiners are never covered and leavers are never removed, and nothing anywhere on screen says so. Reads the tenant's dynamic groups (filtered server-side to DynamicMembership, so a directory with forty thousand static groups costs nothing) and its dynamic administrative units, detects the operator by its documented user.memberof / device.memberof shape rather than the bare word, and reports anything that says memberof WITHOUT matching that shape as read-by-hand instead of dropping it — a scanner that quietly discards what it is unsure about is a scanner whose clean report means nothing. Then it goes further than a scan: every affected group is crossed against the Conditional Access policies ENCA already holds, which turns the retirement into a sentence with consequences in it — an EXCLUSION that stops shrinking is a permanent bypass, an INCLUSION that stops growing is an enforcement gap, and both are named per policy with the policy's own state. Group-based licensing, Entra's own membershipRuleProcessingState (a rule already Paused is already frozen), and the source groups each rule points at are read too, so a rule naming a source group the directory no longer has is flagged as stale TODAY, months before the deadline. Verdicts are critical (an enforced policy or a licence assignment rides on it), high (a real consumer, none of it enforcing), review (no consumer ENCA can see) and read-by-hand. Restricted-management administrative units are called out separately, because their membership decides who is shielded from tenant-wide admins. Owners of the affected groups are read for the owner notification email, which asks each owner to replace the rule, convert to assigned, or say it can go; administrative units have no owner in Entra and the modal says so rather than dropping them. Countdown, Markdown report and full CSV export. READS ONLY and asks for no extra consent — rewriting a membership rule changes who a Conditional Access policy hits, and that decision belongs to a person in the portal. Shipped reading two of the three surfaces Microsoft names and saying so outright, so a clean report was never mistaken for a clean tenant; the third arrived in 0.2. Lives in the Temporary tools section at the top of the home page and is removed once the retirement has passed" },
  toolSmsVoice:     { t: 33, v: "1.7", head: "\ud83d\udcf5 SMS &amp; voice retirement", chips: ["BETA", { txt: "\u23f3 temporary tool", title: "This tool exists for one dated retirement and is removed once the date has passed" }], note: "25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. 1.6: removed the obsolete Microsoft September rollout panel, its check, pause/resume and change-history controls, and the supporting write path. SMS & voice retirement is now read-only. The tenant scan, verdict filters, registered methods and default markers, phone roles, notification draft, Markdown report and CSV remain available. Registration details still require AuditLog.Read.All; refusing consent leaves a scope-only report with unknown registration data. 1.5: Methods registered appears in the table, Markdown and CSV, with the default method first and unknown method names preserved." },
  toolPolicies:     { t: 1, v: "2.20.0", note: "2.20.0 (25484, Mihai: yes build the switch — after the Perfetti import of 23 Sep left 8 new versions Off beside their predecessors): ⇄ SWITCH OVER in 🧹 Housekeeping. Importer.switchCandidates groups every newer version that is Off while an older version of the same CA number is On or Report-only; the newer takes the older's state (On beats Report-only) or Report-only first, is read back, and only then is each older version switched Off and read back — a newer version that does not verify leaves the older ones untouched, an older one that refuses is a partly-done row. Housekeeping's reasons still gate it (names beyond the version, scope, controls) except the two the switch itself resolves; such a pair is ticked only after Compare has been opened; incomplete details cannot be switched. Typed SWITCH, RunLedger, report, reload. ALSO FIXED: housekeeping() stripped only a SPACED version from names, so every -v1.0.3 name (all of CloudFellows) differed beyond the version and no such pair could ever be a cleanup candidate. The Housekeeping button shows the switch count, and 👯 Duplicates says how many CA numbers are at two versions. Six tests in tools/switch-over.test.cjs. 2.19.2 (25466, Mihai: when selecting a policy, it should stay highlighted): THE ROW YOU OPENED STAYS MARKED. Picking a policy in the list filled the inspector on the right and left nothing on the left to say which row it was — and since the list is redrawn on every tick, filter, search or state chip, a mark set on the click would have been wiped by the next redraw anyway. markInspectedRow in js/workspace.js re-applies it from the inspected id at the end of every redraw (refreshViews writes the table, then Workspace.update reaches renderInspector): an accent bar, a tint and the name in the accent colour, plus aria-current for a screen reader. It moves when you pick another row, survives ticking a checkbox (checked in jsdom: the row element is replaced and the mark comes back) and clears on Back to results. 2.19.1 (25456, Mihai: the edit button was all the way on top, every other action is on the bottom, that is why I missed it): ✎ EDIT MOVES INTO THE ACTION ROW. It sat in the card's top strip next to Close — the one strip on the card that carries no verbs — while What-if, Documentation, Backup, Assign, Policy state and Clone in builder were all in the row at the bottom, so the card's own write verb read as chrome and was not found. It is now the FIRST button of that row, marked primary and reading ✎ Edit this policy, with the rest of the row unchanged behind it; renderCardEdit still hides it while an edit is open. Nothing about the edit itself changed. 2.19.0 (25448, R17 — Mihai: editing is not creating; go, name editable on the card, users inline as well): ✎ EDIT ON THE CARD. The policy card's ✎ Edit turns its six boxes into the builder's section forms in the layout the policy was read in, the name editable under the title; a sticky bar counts the settings that change against the policy in the tenant, holds the state (typed ON to switch On), shows the diff and the preflight, and Save PATCHes whole sections, only the changed ones, reads back and re-reads the set (the same pbWrite as the builder). Cancel discards; closing the card or opening the builder ends the edit and restores the builder's own draft. 👥 Assign groups or roles stays the bulk tool. The card and the action bar offer Clone in builder; Edit in builder is gone. 2.18.1 (25445): Edit in builder and Clone in builder on the policy card's action row as well — the card is where a policy is read, so it is where an edit starts. 2.18.0 (25437): \ud83c\udfd7 Open in builder on the action bar — one selected policy opens in T41 Policy builder as an EDIT (whole-section PATCH with a diff of exactly what changes) or a CLONE (a new policy with the next free number in its range); with several selected the first opens and the toast says so;2.17.1 (25435, Mihai: clear filter is not working): CLEAR CLEARS THE VIEW, NOT JUST THE SELECTION. clearSelBtn was `selected.clear(); refreshViews();` and nothing else, so on a bar reading \u201c2 policies in view \u00b7 Nothing selected\u201d it did literally nothing \u2014 while the Overview id filter narrowing that view sat in the chip row above it with its own \u2715. It now clears the selection, idFilter, personaFilter, stateFilter and the search box together, returns early when there is nothing to clear, and updateSelbar disables it and writes a title naming exactly what it would take away (\u201cClear the selection (2), the Overview filter\u201d / \u201cNothing to clear \u2014 every policy is in view\u201d). A button that does nothing is broken, not a no-op. 2.17.0 (25431, Mihai: add to the policy tool a filter bar for the personas): A PERSONA FILTER BAR under the toolbar \u2014 its own row, because the toolbar already wraps on a laptop and a tenant can carry a dozen personas. Render.personaChips(pool, activeSet) is pure and returns the HTML, the same shape as stateChips, so it is unit-tested (tools/persona-filter.test.cjs) rather than only clickable; app.js keeps the Set and mounts it. MULTI-SELECT: several personas at once, a second click unticks, All personas clears \u2014 \u201cAdmins and E-Admins\u201d is a real question. The bar is given the pool the OTHER filters already left, so a count says how many you WOULD get, not how many exist; only personas the tenant has get a chip; a ticked persona keeps its chip at zero so the filter never vanishes under its own empty result; fewer than two personas means no bar at all. Personas come from Render.caGroup, the same CA-number reading the grouped view and the search already use, with 99999 for the unnumbered. NOTE it narrows visible(), so it also scopes Select all and the action bar\u2019s fall-back-to-everything-in-view (Documentation, Backup, Gap analyse) \u2014 said in Help. listRows re-applies state and search to the pool itself, so it is handed an already-persona-filtered pool or the List view would ignore the chips while Cards and Matrix honoured them. Hidden inside Gap analyse with the rest of the policy chrome. UI NOT RUN IN A BROWSER. 2.16.0 (25430, Mihai: add to the assignment options the option to exclude or include guests): \ud83d\udc65 ASSIGN GAINS A THIRD TARGET \u2014 guests & external users, the portal\u2019s third Include choice and its matching Exclude tick. Unlike groups and roles this is ONE object per side, not a list of ids: { guestOrExternalUserTypes: \"b2bCollaborationGuest,serviceProvider\", externalTenants: {\u2026} }, so Set replaces the clause, ADD unions the TYPES, and REMOVE subtracts them \u2014 dropping the whole clause when none are left, since an empty type list is not valid. The tenant scope is a single value that cannot merge, so an ADD onto a policy already scoped to different external tenants is SKIPPED with its reason (Mihai\u2019s call: nothing is silently rescoped) \u2014 a new result state, \u201cleft untouched\u201d, that is neither a failure nor \u201calready set\u201d and carries through the run ledger, the results panel and the change report. externalTenants is an ABSTRACT type: the payload carries #microsoft.graph.conditionalAccessAllExternalTenants or \u2026EnumeratedExternalTenants, without which the enumerated form is rejected. On the include side the clause clears \u201cAll users\u201d, as a role selection does. A REMOVE offers only the types the policies in scope actually carry, pre-ticked, derived from the policies already loaded \u2014 no extra read. ALSO FIXED HERE: newRolesBlock never carried the guest clause through, and conditions.users is PATCHed whole \u2014 so a directory-role edit on a policy holding \u201cexclude service provider users\u201d silently DELETED that exclusion. groupsChanged now compares the clause too, or a guests-only edit would compare equal on every list field and be skipped as \u201cno change\u201d on every policy. tools/assign-guests.test.cjs covers all of it. NOT YET RUN AGAINST A LIVE TENANT. 25408: the results list and the detail pane each scroll on their own, pinned under this screen's toolbar. 25406: Shared list/detail workspace, preserved native actions and flat line icons. 25401: Workspaces navigation, shared tool presentation and full policy details centered with six settings sections and the original definition. Existing actions and confirmations retained. 25390: a 👯 Duplicates set that needs review has a Reviewed tick. The tool will not decide a security question for you — copies that differ in their conditions, controls or guest scope are held — but it will be overruled by somebody who has looked: ticking Reviewed releases that set for selection and merging, the report records that it was released by hand and what had differed, and the refusal that the copy being deleted is the only enforcing one still stands. The page behind the popup no longer scrolls while it is open, the list keeps its scroll position across a tick (27 sets on Courseware jumped back to the top on every change), and closing a comparison returns to the set it was opened from. 25388: 👯 Duplicates says which copy is the newer one. Two runs of the same import land on the same day, so both rows read created 2026-09-17 and the date answered nothing (Courseware, 27 sets). Each row now carries the created time to the minute in the reader's own timezone, the newer or older marker for the set (no marker when the timestamps are equal or the directory gave none — never a guess), and the changed time when the copy was edited after it was made. Graph's None placeholder is no longer offered as something to bring across: it is not a principal, and the tick read Users included: None. 25387: 👯 Duplicates — the same policy twice, which nothing reported. 🧹 Housekeeping reads versions and needs one in the name, so a baseline whose names carry none (Joey Verlinden's) left Courseware holding CA004-Global-…-AuthenticationFlows twice: CA018 Off on the deploy group beside CA019 Report-only on All users. A set is one name carried by two or more policies, the staging prefix aside; a version in the name is Housekeeping's case and the same CA number under two names is a number clash, never a duplicate here. Each set is compared with the PolicyCompare engine for a verdict (identical, assignment differs, needs review) and merged by picking the copy to keep, ticking what to bring across (include groups, exclusions, roles, state — each tick says what it changes) and deleting the rest, behind a plan, a JSON backup, the typed DELETE, the run ledger and a Markdown report. A copy that is On is never deleted while the kept one is not. 25376: the Housekeeping comparison shows SETTINGS, not JSON — a session-controls block against null is walked setting by setting, an authentication strength is one row with its name and id, @odata annotations (which carry the policy's own id and made identical policies compare as different) are stripped at every depth. 25374: always show the full original policy name in list titles, the inspector and rollout selection; remove generated aliases and duplicate subtitles. 25373: Housekeeping Compare shows both policy versions field by field, with highlighted additions/removals, resolved names and a differences-only filter. 25372: Housekeeping includes older On and Report-only versions, explains differing scope and controls, and only offers matching Off predecessors of newer On policies for deletion review. Active-policy deletion acknowledgement restored. 25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25370: local result search suggestions; matching before the 60-option limit; no extra Graph requests. Policy workspace: list first, readable titles with original names, detail inspector, tenant context and grouped actions. Exports abort on missing pages. 2.11: ONE DOOR. The three tiles that opened this same screen are folded in — T02 Create documentation, T04 Backup (JSON) and T05 Set Policy state each called setToolMode and then showed a toast naming a button that was already on the action bar. The bar is unchanged (Documentation, Backup, Gap analyse, Assign groups or roles, Policy state, Delete), and so are the per-card quick actions and every deep link; what changed is that no action is pre-highlighted on open, because there is no longer a tool you came from. The tile is 'Policies' and its blurb names the five verbs, since a fold that leaves the home page saying less than it did is a fold that hid something;2.10.1: the group popup on a policy card says whether NESTING is disabled — 🚫 disabled, allowed, impossible on a role-assignable group, or not reported — read from v1.0 next to the member preview. 2.10: 2.10: 🎯 Assign's Apply and 🎚 Set policy state show the run ledger in their dialog — every policy listed before the first write, the one being written marked, ✓ or ✗ per row with the reason inline, the box scrolling to the working row, a count and a clock, Stop between writes; a run with failures keeps the dialog open so the ✗ rows are read where they happened. 2.9: the green action bar slid underneath the toolbar and took its own first line with it \u2014 on a two-row bar that hid N policies in view entirely and left a strip of buttons apparently floating under the filters. The sticky offsets were measured at a few chosen moments, and these boxes change height for reasons nothing calls a resize: chips rendering after the policies load, Select all growing from (0) to (105), a second open tab wrapping the tool nav, the toolbar wrapping its actions. A ResizeObserver on the header, the tool nav and the toolbar recomputes when they actually move; 2.8: \ud83d\udc65 Assign gains an eighth action \u2014 RESTORE each policy's own CAxxx-Exclusion group. The only action that aims a DIFFERENT group at every policy: the CA number in the name resolves to its exclusion group through the baseline catalog (derived by convention, and labelled so, when the catalog has no such number). Step 2 is a drift report \u2014 already correct / lost the reference / group not in this tenant / no convention group \u2014 with only the repairs pre-ticked, missing groups creatable from their templates, and the whole tenant as a scope for the sweep. Additive only; tenant-wide asks for the typed ALL, because an exclusion widens a policy. Also fixes the 2.7 REMOVE panel, which threw \"asAssignedGroups is not defined\" for anybody who had not visited the Directory-roles branch first \u2014 its helpers were declared inside that branch and are at module level now.;2.7: the two REMOVE actions in \ud83d\udc65 Assign groups or roles now list the assignment the selected policies ACTUALLY have \u2014 pre-ticked, so the work is unticking what should stay \u2014 instead of the baseline catalog, where ticking a group the policy never referenced did nothing and the group you wanted to take off might not appear at all. Names are read per id, a group the directory no longer has is labelled a dangling reference rather than shown as its own GUID, and each row says how many of the selected policies carry it. A tenant-wide removal now needs the same typed ALL as a tenant-wide rewrite; the expanded card carries the policy id, and every attribute built from an id is escaped;2.5: a guest/external selection names its user types instead of collapsing to one line — which of the six are in it decides whether the policy reaches your CSP partner's delegated admins, and an omitted service provider is called out as NOT service providers; a selection scoped to named tenants says how many;the per-policy what-if flow closes with a 🎯 CA result card: the actual sign-in verdict (denied / succeeds after which controls / session shaping) plus the tenant reality — Enforced today, report-only (recorded, not enforced) or Off (becomes real when switched On);list and summary say how many more include entries there are instead of showing only the first;usable on a phone — non-sticky toolbar, single-column policy cards, scrolling state filters, scrolling list table, two-row action bar;cards / list / settings matrix, persona grouping, dependency inspector, full-screen matrix, selection actions, delete with typed confirmation, per-policy what-if flow, per-persona apply flow, housekeeping (delete superseded Off versions)" },
  toolDocument:     { t: 2, v: "1.7.1", folded: { into: "toolPolicies", build: 25338 }, note: "1.7.1: folded into T01 Policies (build 25338) — the tile is gone, the Create documentation action on the policy action bar and the per-card quick action are what they always were, openExport is unchanged, and this Help section moved under Policies keeping its own name;1.7: on a baseline tenant the document describes the BASELINE CATALOG, not the tenant — scoped to the persona CAxxx policies through the same helper 🗄 Backup uses, with the scope stated in the modal and carried into the deliverable itself (PDF cover line, Markdown blockquote, Word title, SCOPE.txt beside the PNGs). The restricted-unit appendix is deliberately not filtered: those units are the baseline’s own persona vaults.;1.6 (R28): the restricted-unit pages carry this tenant\u2019s group \u2192 persona mapping, so a group sitting in a vault its name does not explain is accounted for in the document rather than looking like somebody\u2019s mistake;1.5 (R27): Word, PDF, Markdown and the PNG bundle can include auditor-ready restricted-administrative-unit pages in the same document as the policies — per unit: persona, protected groups, every CA include/exclude dependency, scoped administrators and role-definition-verified group-membership capability, with no-admin, empty, frozen and unreadable states called out. The appendix reads its own data and fails soft: a denied or broken optional integration never blocks the policy document. Word, PDF, PNG and PNG-bundle export with tenant branding" },
  toolAnalyze:      { t: 3, v: "1.16.0", head: "\ud83d\udd0d Gap analyse \u2014 Conditional Access impact", note: "25413: COHORTS. Users whose state is identical across every policy in the run are one row — the same collapsing T09 has always done for exclusion patterns — so a tenant of thousands reads as a handful of cohorts plus its outliers, and a cohort of one sorts to the top because that is the interesting row. Opening a cohort lists the users behind it. Also: the users table no longer looks each rendered row up with indexOf, which made the render quadratic in the number of users (a 50,000-row probe produced 23.6 MB of HTML). 25412: results are bound to the run that made them (js/runmeta.js). A strip above every result states tenant, policy snapshot time, policy states, population, completeness and a run id; a policy reload, tenant change or sign-out DROPS the results computed from the previous snapshot instead of leaving them on screen under a new tenant, and the strip turns amber if the snapshot moves under a result. Run is guarded by its own busy state rather than by the button being enabled, so a scope change during a run cannot start a second job over the first one’s report; stopping a run reports STOPPED instead of raising a second uncaught error from the cancellation guard it just failed; and the exported report’s header is read from the run descriptor, not from the form, so changing the scope without rerunning no longer rewrites the description of a file whose contents did not change. 25409 (1.14.0): ONE comparison for both tools, js/coverage.js. A bypass is covered only when the replacement gives the SAME people the SAME protection \u2014 one shared grant control is a candidate, not an answer, so MFA plus compliant device is no longer closed by an MFA-only policy. Four states: equivalent, partial with the missing requirement named, none, not established. A condition the comparison does not model (device filter, authentication context, authentication flow, application filter, insider risk, terms of use, session controls) costs the verdict its green rather than passing silently. Policy IDs travel through the report, the matrix map, the column headers and the detail links, so two policies sharing a display name no longer share one cell. Funnel stages say TARGETED BY AN ENABLED POLICY and TARGETED BY AN ENABLED MFA POLICY, which is what an identity assignment proves; enforced is reserved for What-If and sign-in evidence. 25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25370: local result search suggestions; matching before the 60-option limit; no extra Graph requests. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. Membership failures abort coverage; optional MFA is not mandatory MFA. 1.10: the funnel's last stage has its own tab. T31 Licence gap computed the same obligation this funnel already reports through LicGap.licenceOf — every user a policy targets needs Entra ID P1, a risk condition needs P2 — and then said how to close it, so it is that stage opened up rather than a second tool. It is the Licences tab now. One mechanical note worth keeping: this tool IS screen-list in its analyze view and screen-list is also T01 Policies, so the strip is UNMOUNTED when Policies is opened (unmountToolTabs) — the only host that needs it, because it is the only host sharing a screen with another tool;1.9.3: the named user / group box — picking a suggestion from the search box no longer reopens the list over the filled field — choosing from the list fires the same input event as typing, so the pick re-ran the search and the browser reopened the dropdown. 1.9.2: every coverage row is a filter. A row used to be clickable only when somebody had dropped out of it — Required to do MFA at 100% was dead. Now clicking a row lists the users who GOT that far, and its −n lists the ones who did not, so both halves of every stage open. 1.9.1: the header carries the T03 chip like every other tool (it was the one screen without it), and the ← Back to policies button is gone — the tab bar already leads back to List Policies, and a second Back control on the screen read as a stray. 1.9: 1.9: the tool renders inside the List Policies screen, and that screen's Cards / List / Matrix picker was left showing over it \u2014 switching AWAY from Gap analyse rather than within it, with nothing highlighted, and its Matrix meaning a different grid from this tool's own Matrix tab. Replaced here by one labelled \u2190 Back to policies, which returns you to the view you came from; 1.8: a coverage flow above the results \u2014 in scope \u2192 targeted \u2192 covered by an ENFORCED policy \u2192 required to do MFA \u2192 licensed for what they are targeted by, each bar against the same denominator so the drops are readable at a glance; every drop clicks through to exactly those users, and the drop sets are deliberately not the summary cards\u2019 sets. The licence stage reads its own data (assignedLicenses on the user read it already does, plus /subscribedSkus) through LicGap.licenceOf, so \ud83c\udfab Licence gap and this tool cannot disagree about a user \u2014 and a refused read renders as NOT READ rather than as zero;1.7 (R29): a run can be scoped to named users or groups — a group expanded to its members, nothing read tenant-wide, and the result says what it was scoped to;users × policies impact matrix, group filters, standalone HTML report, scoped matrix columns" },
  toolGapCheck:     { t: 8, v: "2.4.1", head: "\ud83d\udee1 Best-practice &amp; bypass checks", note: "2.4.1 (25479): checkOr reads an authentication strength (as the MFA side) and a terms of use as grant options too. From builtInControls alone, MFA strength OR compliant device had one control and was never judged, and MFA OR terms of use — accept the terms, skip MFA — was invisible; the second is High, and the finding names the strength and says a click on the terms is not a second factor. 2.4.0 (25476, from the CloudFellows baseline export): TWO CHECKS THAT READ THE POLICY SET AS A WHOLE. Group Hygiene: two or more groups referenced by Conditional Access that share one display name, each id listed with the policies that use it — the baseline had two CAB-SEC-U-Persona-Externals, the Externals MFA policy on one and CA000's exclusion on the other. Allow-List Block: an unconditional block on All users and All resources excluding three or more groups is an allow-list; it is reported (high) when it misses a group another active policy INCLUDES, or a group two or more other All-users policies exclude (the shared-device accounts), and (medium, or folded into the same finding) when it blocks service provider, B2B direct connect and other external users, who can never be in a group. A block with any location, platform, client-app, risk, device or auth-flow condition is not an allow-list. The run now gets the tenant load's resolved names (policyResolve.names) so both checks name groups, not GUIDs. Two tests; on the real export they reproduce items 1, 2, 3 and the CA099 half of 5 of the review. 2.3.0 (25473, the open items of the audit): TWO CONTROLS NOTHING LOOKED FOR, AND A COLUMN THAT COUNTED THE WRONG THING. New tenant checks: Security Info Registration — no enabled policy targets the Register security information user action (urn:user:registersecurityinfo) with MFA or block, so the first person with a user's password chooses that account's MFA method from anywhere; since 6 July 2026 the action also covers Windows Hello for Business and macOS Platform SSO registration; medium, low when the policy exists but is report-only or Off; remediation is Learn's template (All users minus break-glass and guests, any location except trusted, authentication strength, TAP for new users). Authentication Flows — no enabled block on the device code flow for all users on All resources; medium, low when it is narrow or not On; remediation names the Teams Android exception. PERSONA MATRIX: the Sign-in frequency column also counted a policy that only set persistent browser to never, so an admin persona without any sign-in frequency read as covered; it counts sign-in frequency only now, and its gap finding carries its own where / change / why. An admin-roles check was drafted and dropped: role-scoped policies already land in the Admins row structurally, so it could only repeat the matrix. Scorecard signals link the new categories. Three tests in tools/gapcheck-audit.test.cjs. 2.2.0 (25470, the T07/T08 audit): SIX CHECKS THAT SAID MORE THAN THEY KNEW. MFA for all users was cleared by an All-users policy asking MFA for ONE app — it must be All resources now, and a partial one is its own high finding. Legacy authentication blocked was cleared by a block on a single pilot group — tenant-wide now means everyone, All resources and BOTH legacy client types, and a narrow block is reported with the reason. Grant OR was always High as the weakest link: MFA OR a compliant / hybrid-joined device is Microsoft\u2019s own template and reads low, MFA OR app protection is the real way around MFA and reads medium. The guest strength check fired on every guest MFA policy and contradicted the MS Learn tab — a guest who is not trusted simply registers MFA here; it now fires only when EVERY combination of the strength needs a home-tenant method. Guest-only policies are no longer asked to exclude break-glass. An opened finding stays open when the severity filter changes (keyed on policy and title, not on its index). RECOMMENDATIONS REWRITTEN as where / change / why for legacy block, sign-in risk, user risk (Require risk remediation, guests excluded), FOCI, bypass apps, device registration, grant without MFA and persona coverage. tools/gapcheck-audit.test.cjs (6). 25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. Evidence desk prioritizes findings alongside assessment, recommendation and context completeness. 2.0.1: the tab strip takes its own line. It was already first in the toolbar flow, but the toolbar wraps, so at desktop width four tabs sat shoulder to shoulder with five severity chips — a nine-item row where only four of the items change the tool. The strip is a full-width track now, tabs left and empty rail right, the same shape as the tool tabs in the header. One CSS rule, so all six tabbed tools follow;2.0: THE HOST of the checks. T07 MS Learn checks, T21 CIS Benchmark and T30 Device reality check are folded in as RULE PACKS and the tile is Checks. All four answered one question — what is wrong with this baseline, judged against a reference — and each had its own tile, its own Refresh and its own Export MD, so a review meant opening four tools in turn. Each pack still asks for its own permissions on its own run rather than on tab open, which is what stops reaching Checks from prompting for Intune scopes nobody was going to use. DELIBERATELY NOT DONE, and said on the screen rather than left as a gap: one findings table across the four. They present a persona-by-control matrix, findings with buildable fixes, a four-tier CIS score with an L1 and L2 filter, and a per-policy-per-platform grid — different shapes, and one table with a Source column would lose what each of them says. That is its own decision;1.9: the baseline-scopes check reads the tenant's Baseline scopes setting (portal API, cached per load) and grades from it — DISABLED is High, Customize behavior lists the policies excluding the placeholder app (low when none does, because then the setting changes nothing), default/enabled is an info that says the exclusions no longer exempt baseline-scope sign-ins, not-read says so; wording moved from “March 2026, coming” to “rolled out from June 2026” with the full scope list and the Learn page;1.8: a grant OR spanning compliant/hybrid device AND app protection (MDM-or-MAM) is the accepted pattern (info), not a weakest-link High — only an OR mixing in MFA, password change or terms of use stays High;scorecard pillars and signals are clickable and filter the findings list to their related categories (severity chips count the filtered view, ✕ chip or All clears);legacy-auth per-policy finding correlates with the tenant's dedicated block — LOW when an enabled tenant-wide block covers it, MEDIUM when the block is narrower, HIGH when there is none — and the scorecard signal mirrors it (100 full / 70 partial / 50 report-only / 0);Zero Trust scorecard (3 pillars, weighted 0-100 signals) on the summary and in the Markdown export; 7 new checks: risk-based-policy gaps, Microsoft-managed policy detection (incl. disabled phantom drafts), platform-scoping without an unknown-platform block, named-location hygiene, MFA client-app-type coverage, disabled resilience defaults, authentication-context / Protected Actions validation; bypass checks, persona × control matrix, deployed-but-Off state, Markdown export" },
  toolExclusions:   { t: 9, v: "1.18.0", head: "\ud83d\udeaa CA Exclusion analyzer", note: "25418 (1.18.0): what narrows the grid is a CHIP, not a side effect. Pinning a row or a policy puts a removable chip in the toolbar beside the type chips, so one place owns what is narrowing the view; the banner above the grid is only the selected-policy strip now. Pinning one row AND one policy draws the answer — the evidence card for that pair — instead of a full grid with a single mark in it. Below 700px the Matrix tab is not offered; the Exclusions list carries the same facts, ranked. 25417 (1.17.0): the grids work by touch and by keyboard. Every marked cell is a button that opens an EVIDENCE card — who, why, the policy’s state, the three-state verdict for a user, the coverage verdict for an app, the odd-one-out sentence for a gap — with Open policy, View members, Only this row and Only this policy on it; the reason used to be a hover title, invisible on a phone and unreachable from a keyboard. Row labels and column headers are buttons too, and the arrow keys walk the grid (one roving tab stop, so a large grid is not two thousand tab presses). Column headers are capped at 110px and the full policy name, state, controls and exclusion count move into the selected-policy strip when a column is picked. A legend above each grid says what clicking does, not only what the symbols mean. 25416 (1.16.0): two controls that did not work as controls. The group member button in the matrix was a 13px line INSIDE the row’s clipped sublabel, so a normal click landed on the row’s filter instead — it is now its own button on its own line, sized to be hit. Full screen used to take the toolbar and the grid into the modal and leave the pager behind it, so page 1 was all there was; the pager parks in the modal with the rest. 25415: the tool says what its member counts mean. Help now separates the two questions that were answered in one bullet — WHO is excluded (transitive membership: a user who is only in a group nested inside the excluded group is counted, exactly as Entra evaluates, paged in full, users only, and the scan stops rather than publishing a short count) and HOW they got there (a separate read, first 40 nested groups per run, anything else PATH NOT RESOLVED) — and names the two populations that are deliberately not expanded, excluded directory roles and guest clauses. The group member dialog carries the same sentence where the question actually comes up. 25414: a scan in flight owns the screen. Since 25412 nothing is published until the read finishes, so reopening the tool mid-scan repainted the idle run prompt underneath the busy panel, with the toolbar and its export buttons beside it. openExclusions, renderExclusions and the idle screen respect the busy state now, and the toolbar is hidden while a read runs — search, the tab picker, full screen and both exports all act on a published result and there is none yet. 25413: the LIST is the default view and the grid is the expert one. A matrix is a poor inventory — on the demo tenant it is 96 cells with 16 marks and five of the eight exclusions appear in exactly one policy — but it is the only view that shows the ODD ONE OUT, so it now does that job outright: where most policies on screen carry an exclusion, the shared pattern is muted and the policies that do NOT carry it are marked, with a line naming them. 25412: results are bound to the run that made them (js/runmeta.js). A strip above every result states tenant, policy snapshot time, policy states, population, completeness and a run id; a policy reload, tenant change or sign-out DROPS the results computed from the previous snapshot instead of leaving them on screen under a new tenant, and the strip turns amber if the snapshot moves under a result. The scan publishes nothing until the whole run succeeds — the model used to be assigned before resolution finished while the previous run’s user rows were still on screen, with working export buttons. 25410 (1.13.0): CONFIGURED and EFFECTIVE are two different facts. A user listed in an exclusion is only bypassing when the policy would otherwise have INCLUDED them; a policy scoped to one group that also excludes the break-glass account never addressed that account, and counting it as a bypass inflated the number. Every cell is now one of three: effective bypass, configured only, or not established because the include side names a group or role this scan did not read. Excluded directory roles are named as NOT EXPANDED instead of contributing a silent zero. The external-user clause is kept whole — types, tenant kind and tenant ids — so two partner-specific exemptions are two rows and only a genuinely all-external clause raises the all-guests flag. Both relationship reads follow their continuation links, so a direct member on page two is no longer reported as arriving through nesting, and membership completeness is tracked separately from PATH completeness: an unresolved route says path not resolved rather than inventing one. 25409 (1.12.0): the app-coverage question is answered by the shared comparison (js/coverage.js), the same one T03 uses. A covering policy now has to reach the same users with the same conditions and the same controls — its own exclusions are subtracted, its platforms and locations compared, its grant controls compared — and the answer is equivalent, partial with what is missing named, none, or not established. Office 365 and Microsoft Admin Portals are resource COLLECTIONS and say so instead of being skipped in silence. An app nothing reaches reads NO EQUIVALENT COVERAGE ESTABLISHED BY THIS ANALYSIS rather than claiming it has no Conditional Access at all. 25408: the results list and the detail pane each scroll on their own, pinned under this screen's toolbar. 25406: Shared list/detail workspace with native actions and flat icons. 25370: local result search suggestions; matching before the 60-option limit; no extra Graph requests. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. 1.9: two questions every app exclusion now answers — is the app COVERED by another enabled, enforcing policy for the same users (High in the risk review when nothing reaches it, info naming the covering policy when something does), and does the app EXIST here (a GUID with no service principal is a phantom exclusion: matches nothing today, goes live on consent — medium); row chips, header chips and the Markdown report carry both;1.8: an excluded application id with no service principal in the tenant is named from the first-party app map (labels.js FIRST_PARTY_APPS) instead of showing as a bare GUID;1.7: nesting in sight. Every excluded group already expanded to its transitive members, so users who arrive through a nested group were counted — but not shown as such, and an exclusion group with 0 direct members and 136 through nesting read as 136 excluded users. Now the scan also reads each excluded group's direct members and the nested groups' members (two batches), so: the matrix row says ↪ all through 9 nested groups, the member list names the nested group each member came through (direct first), the effective-users matrix shows ↪ for a user who is excluded through nesting only, the head counts users through nesting, and the risk review flags it — Medium for nested groups inside an excluded group, High when an exclusion group is fed entirely by nested groups, because whoever manages those groups decides who bypasses the policy. CSV and Markdown carry the path. 1.6: exclusion × policy matrix (default, unmerged), effective-user view and risk review (governance flags per policy, patterns after Tiago S. Carvalho), click-to-filter rows and columns, group member list, CSV and Markdown" },
  toolValidator:    { t: 13, v: "1.8.2", head: "\u26a1 CA validator", chips: ["NEW"], folded: { into: "toolWhatIf", build: 25346 }, note: "25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25370: local result search suggestions; matching before the 60-option limit; no extra Graph requests. Unknown external-user scope is explicitly skipped. 1.7.1: folded into T14 What-If (build 25346) as the Every simulation mode. The simulation generation, the target narrowing, the control filter, the compact and full views and the export are untouched; openValidator is unchanged and keeps its callers;1.7: IT COUNTS GUESTS NOW, and that changes the numbers. This tool's own scope check read includeUsers, includeGroups and includeRoles and nothing else, so a policy assigned to Guests and external users was reported OUT OF SCOPE for a guest it actually reaches — and every simulation that policy implies for that guest was skipped. 🕵 Who is Anna to CA had always counted the guest type, so the two tools disagreed about the same person. There is one scope check now, js/cascope.js CaScope.of, built from the more complete of the two; appliesTo delegates to it and keeps its field names. A guest target therefore produces simulations where it produced none, the target bar says so outright with the build number, and the count is higher than it was. For a member or a group target the verdict is untouched — 120 policy-by-subject comparisons agree on whether the policy applies — but ONE WORD moves: a target in a policy's exclusion group that was never in its include scope used to read excluded and now reads not targeted, because the old check looked for an exclusion independently of the include. That is what 🕵 has always said about the same person, and removing the disagreement is the point;1.6.1: the target box — picking a suggestion from the search box no longer reopens the list over the filled field — choosing from the list fires the same input event as typing, so the pick re-ran the search and the browser reopened the dropdown. 1.6: per-policy sign-in simulation report ported from Jasper Baes' Conditional Access Validator — expected control per user/app/client/location/platform/risk, inverted 'no control' for excluded scope, report-only toggle, filter/search, Markdown export (no Maester code, representative placeholder users), click a policy name to open its card — out of BETA" },
  toolWhatIf:       { t: 14, v: "1.5.1", head: "\ud83e\uddea What-If", note: "25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. Device and restricted external scope uncertainty is explicit; insider risk strings are evaluated. 1.4: THE HOST of the what-happens question, both directions. T13 CA validator is folded in as the Every simulation mode: this tool evaluates one described sign-in against every policy, that one enumerates every sign-in a policy implies. The consolidation plan set a condition on folding these two — they must not be able to disagree about the same policy and the same person — and it holds as of the two builds before this one: 25344 removed a dead second simulator so both go through WhatIfEval.evaluate, and 25345 gave them one scope check. The form is a form and not a toolbar, so the mode strip sits in an otherwise empty toolbar above it, at the same height it has on every other host;1.3.2: js/whatif.js lost 195 lines of DEAD CODE and nothing on screen changed. The module carried a second scenario simulator — resolveSubject, evalPolicy, simulate, renderSim — written before js/whatifeval.js existed, exported, and called by nothing: this tool evaluates through WhatIfEval.evaluate, and so do Compare users and Apps with no service principal. Dead code that answers a question the app answers elsewhere is worse than no code, because it reads as authoritative and it drifts: WhatIfEval has since learnt user actions, authentication contexts, insider risk, authentication flows and device filters that the fork never knew. It is also what made the consolidation review count THREE policy evaluators in ENCA when there has only ever been one in use — validator.js appliesTo, the third, answers a different question (is this principal in the policy's user assignment) and is a duplicate of whois.js stateFor instead. The stylesheet lost the eight rules only the deleted half used;1.3.1: picking a suggestion from the search box no longer reopens the list over the filled field — choosing from the list fires the same input event as typing, so the pick re-ran the search and the browser reopened the dropdown (the user box; the app box already resolved a pick locally). 1.3 (R30): the policies that did not apply filter by persona, CA number and reason, with a count per reason first — the same CA ranges List Policies groups by, through the same helper;1.2 (R31): the target resource is searched by name over the tenant's own service principals instead of asking for a raw GUID; a pasted id is resolved to a name for confirmation, and an id with no service principal here is reported rather than refused because a policy can legitimately name one;1.1: the verdict names the policy that would BLOCK — clickable, and marked in the list — and no longer counts report-only policies as blocking: a scenario whose only Block policy was staged came back as \u201caccess would be blocked\u201d for a sign-in that succeeds today. Report-only blocks are reported as \u201cwould block once enforced\u201d, and the Markdown export carries the same. Entra Conditional Access What If tool re-implementation — simulate a sign-in (identity, resource, platform, client app, IP/country, device state, risks, auth flow) and get the policies that apply with their grant/session controls plus the policies that don't and the first unmet condition; named-location CIDR and country matching, Markdown export" },
  toolGroupUse:     { t: 19, v: "1.5.1", head: "\ud83d\udd17 User or Group analyzer", note: "25408: the results list and the detail pane each scroll on their own, pinned under this screen's toolbar. 25406: Shared list/detail workspace with native actions and flat icons. 1.4.0 (25382): two Intune-area sources — Windows 365 Cloud PC (provisioning policies and user settings, CloudPC.Read.All) and Intune role assignments (members and resource scopes, both directions, DeviceManagementRBAC.Read.All) — and the enrolment source named for what it reads (platform restrictions, Enrollment Status Page, Windows Hello for Business, notifications, co-management authority) instead of “platform restrictions” with a raw type tail. 25370: local result search suggestions; matching before the 60-option limit; no extra Graph requests. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. 1.2: THE COUNTS ARE VERDICT TILES. They were grey pills whose only states were grey-when-zero and green-when-picked, so three ids a policy still names that the directory no longer has read exactly like twenty-four groups. Each count is a tile now with a colour when the figure is a problem, and it is still the jump or filter it always was. The sweep states its two findings in words above them. The per-area blocks fold, remembered per card, the way the cards in the wave and Who-is views already did. And the strip pins where the result begins instead of at a hard-coded 106 pixels, which had it sitting on top of this screen own toolbar since build 25353;1.1.1: picking a suggestion from the search box no longer reopens the list over the filled field — choosing from the list fires the same input event as typing, so the pick re-ran the search and the browser reopened the dropdown. 1.1: renamed from Group Analyzer to User or Group analyzer — the tool has taken a user as well as a group since 0.1, and the old name made half of what it does invisible from the home page. Name only: tile, sidebar, header, Help and cross-references; report file names and the tool id are unchanged, and Jasper Baes' Microsoft Cloud Group Analyzer keeps its own name in the credit. 1.0: out of BETA — where an Entra group is actually used: 23 services across Entra ID (nesting, administrative units, directory roles incl. PIM eligibility, enterprise apps, group-based licensing, authentication methods policy, Conditional Access, access packages, admin-consent reviewers, registration state), Intune (enrolment restrictions, compliance, configuration profiles, scripts, app protection, app configuration, app assignments, Autopilot, Windows update profiles), Microsoft 365 (M365 group / Team) and Azure RBAC across subscriptions and management groups; one group or user, or a tenant-wide sweep with an unused-groups view; parent-group inheritance shown per hit; per-area consent; Markdown, standalone HTML and CSV export. 0.2: sweep rows open a popup built from the sweep data instead of re-scanning (with Deep analyze for parent expansion), HTML report added, Intune scripts now request DeviceManagementScripts.Read.All and entitlement management uses single-level expands with a candidate ladder (both were failing), and every failure says which permission and which role it needs. 0.3: sweep can be narrowed by name prefix / suffix / substring, and drilling into a group keeps the sweep loaded behind a Back button. 0.4: default sweep scope is the groups Conditional Access actually assigns — taken from the policies already in memory, no directory enumeration — with dangling references (an id a policy names but the directory no longer has) kept and flagged; summary chips ride in a sticky strip so the counts and filters stay reachable on a long result. After Jasper Baes' Microsoft Cloud Group Analyzer" },
  toolWhoIs:       { t: 36, v: "1.4.3", head: "\ud83d\udd75 Who is Anna to CA", chips: ["BETA"], note: "1.4.3 (25405): A POLICY CAN NO LONGER GO MISSING FROM HER LIST. A policy whose guest scope names specific external-user types \u2014 Guests & external users: Service provider users, the usual one on a tenant with a CSP \u2014 could not be resolved for anybody, because the scope check was never given the external-user type it needed and answered I cannot tell. That answer is a fourth state, unknown, and it belonged to no filter chip: the row was reachable only under All, so a policy that plainly reached the person was absent from Reaches her, from Excluded and from Not targeted alike, and the three counts did not add up to the fourth. The type is derived now from userType and the #EXT# marker in the UPN, so an internal account is answered outright \u2014 a principal holding an account in this tenant cannot be a service provider user or a direct-connect user, since neither has one \u2014 and the rows resolve. Where it genuinely cannot be decided the state is kept, given its own amber chip, counted on the tile as unresolved, sorted above Not targeted and explained in a callout that says which half could not be decided. Shared with \u26a1 CA validator, \ud83c\udf0a the wave, \u2696 Compare users and \ud83d\udcca Analyze through js/cascope.js. 1.4.2 (25404): Original policy names including their own CA number are shown in full, without an additional ENCA sequence prefix. 1.4.1 (25403): T36 rail shortcut and compact CA-number policy references; full details and export names retained. 1.4.0 (25381): WHAT SHE SIGNED IN WITH. The 🔐 card opens with the methods she used across the window (Password ×120, Microsoft Authenticator ×30, by a claim in the token ×85), the authentication strengths she was held to, and a red callout for every sign-in that asked for MFA or a strength and got a password only — with the apps, the newest case, and, when the strength was phishing-resistant and no passkey, FIDO2 key, Windows Hello or certificate appears in the window, the plain conclusion that the METHOD is the fix, not a policy. The third tile reads Asked, not given when that happened (it used to count such a sign-in as a fresh prompt — the password row carries the requirement too, and the old step check read it as the second factor). The policies-that-demanded-MFA column now includes the policy that FAILED the sign-in for want of the factor. The stopped table prints 🔑 what was used under each result, with the steps in the tooltip; the Markdown brief carries all of it. Hunting rows say the steps are not in that source. 25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. Stable subject-tab position and compact tool introduction. Restricted external scopes preserve tenant and type and show unknown scope. 1.0: THE HOST, and the tile is Who is … to CA. T37 Who is the wave to CA and T18 Compare users are folded in as SUBJECTS: a user, a group, or several users side by side. They were three tiles over one picture and the code always said so — the wave resolves every member of a group through this tool's own policy ladder (WhoIs.stateFor), and this tool resolves its user through Compare's resolver (Comparer.resolveUser) — so the three were siblings with three doors. Since 25345 they also share one scope check, which is what makes a single tool honest: three subjects that could disagree about the same person and the same policy would be worse than three tools. Compare's controls are a form rather than a toolbar, so its subject strip sits in an otherwise empty toolbar above it, the same way What-If's does;0.9.1: stateFor delegates to the shared scope check (js/cascope.js, build 25345) instead of carrying its own copy. Its logic IS the shared one — it was the more complete of the two and became the base — so the three states, the named include reason and the direct-versus-nested detail are exactly what they were; howOf is passed in, because direct versus nested is this tool's question and not the scope check's;0.9: 📵 RETIRED CONTROL. Require approved client app was retired on 30 June 2026 — a policy carrying it is read-only (the policies table marks it) — and the day it is replaced or removed, whoever satisfied it through the app on a non-compliant device is blocked unless an Intune app protection policy already reaches them. Per retired policy reaching her: the sign-ins that went through the approved-app path, apps, devices, last; verdict blocked the day the control goes / ready for the replacement (an app protection policy already satisfied on a non-compliant device) / not affected. 0.8: “no data” told apart from “out of scope”. A report-only policy that reaches her by assignment and was evaluated on her sign-ins with every verdict “not applied” — no legacy client, no risk, not that app — now reads OUT OF SCOPE ON HER SIGN-INS with the evaluation count, in the tile, the callout, the Forecast column and the export; it used to say “no data”, which was the opposite of what happened (Perfetti: six policies, 7,111 evaluations each, none matched). “No data” is kept for a policy that appears on none of her records at all, and the callout says what that means. Every card folds on its heading — click to fold or unfold, remembered per card. The line under Identity risk says in plain words where each part comes from and that dismissing or confirming a risk happens in the Entra portal. 0.7: 🔐 MFA ON HER SIGN-INS — the answer to “he keeps getting the Authenticator prompt on app X, which policy is it?”. A prompt the user completes is a SUCCESSFUL sign-in, so the stopped table never shows it; this card does: per app, the applied policies that demanded MFA (result success with an MFA or authentication-strength grant), how many sign-ins required it, and — from the record's authentication steps — how many were a FRESH prompt versus a claim already in the token, from how many devices, and the last fresh prompt. Callouts say why: fresh prompts spread over many devices (a non-persistent VDI pool is one prompt per host), session controls reaching her (sign-in frequency, non-persistent browser), or every requirement satisfied by the token — in which case the prompt she sees is not Conditional Access. Hunting rows carry the requirement but not the steps and count as not known. 0.6: everything from HER side. The 🛡 Identity risk card lists only the risk-based policies that REACH her — the same include/exclude resolution as the policies table — with a one-line count of the ones that do not (not targeted, or excluded); 0.5 listed every risk policy in the tenant. Insider-risk policies show their levels. Policy numbers everywhere in the tool are the BASELINE's — CA012 from “(NEW)CA012-BLOCK-…” — not ENCA's running number (the same rule 👥 CA groups 5.9.6 adopted); a name without a number shows in full. New 💻 Devices card: every device she signed in from in the window, with what Conditional Access saw of it — Compliant, Managed not compliant, Registered not managed, or Unmanaged — sign-in and stopped counts, last seen, the apps; and a callout when a compliant-device grant reaches her and sign-ins came from devices that cannot meet it. The stopped-sign-ins table carries 🚦 Sign-in failures' why: the control each policy demanded and the error code in words (MFA demanded and not completed, compliant device required and this one is not). 0.5: IDENTITY RISK. A fifth tile says what Identity Protection thinks of her — at risk and at which level (low / medium / high, or confirmed compromised), since when and why, or remediated / dismissed / confirmed safe / never flagged — and names the risk-based policy that FIRES on that level right now. Risky sign-ins in the window come off her own sign-in records (no extra read): the count per level, and a 🛡 Identity risk card listing the detections of the last 30 days (type, level, state, activity, where) and the risky sign-ins (aggregated level, state, detection types, CA outcome, Replay). The user record and the detections are an optional read — IdentityRiskyUser.Read.All + IdentityRiskEvent.Read.All, asked on the click or read straight away when already granted; a tenant without P2 is told so. And the policies table gets a STATE filter row — Any / Enforced / Report-only / Off, with counts that follow the reaches-her chips. 0.4: picking a suggestion from the search box no longer reopens the list over the filled field — choosing from the list fires the same input event as typing, so the pick re-ran the search and the browser reopened the dropdown. 0.3: nested is loud. The tool already knew whether she is in a group directly or nested via another (one memberOf read plus a batch of transitiveMemberOf over her direct groups) and wrote it in grey. It is now marked ↪ in red wherever a group reason appears — the exclusion rungs, the Reaches-her-via column, the standing-bypass callout — with the note that whoever manages the nested group decides, and that she was never added to the exclusion group itself. Demo shows one nested exclusion. 0.2: the Sign-in SOURCE segment — Entra sign-in log (interactive, capped at 10,000, AuditLog.Read.All), Defender hunting (the same interactive sign-ins from EntraIdSignInEvents through Graph runHuntingQuery, ThreatHunting.Read.All, no cap, 30 days) or Hunting + non-interactive (token refreshes and background client sign-ins too, which the Graph list never returns). Chosen once per tenant and shared by 🚦 🎚 🕵 🌊 with one cached window per source; the hunting read is one query per day so every response stays under the 50 MB cap, a day that hits the 20,000-row cap is said to be capped, and the table name falls back to AADSignInEventsBeta until its retirement on 19 October 2026. Needs Entra ID P2 for the table to be populated. On the hunting source her sign-ins are one filtered query on AccountObjectId, all days at once. 0.1: new, BETA — in production as build 309. One user, the whole Conditional Access picture on one screen — the answer to “why can't Anna sign in” and “is Anna in the wave yet”, which used to take four tools. Four tiles first: her DEPLOYMENT STAGE (which of the active baseline's CAD-SEC-U-DG-* groups she is in), how many policies REACH her (enforced / report-only / off, and how many exclude her), how many sign-ins Conditional Access STOPPED in the window, and what happens to her IF EVERYTHING IN REPORT-ONLY WENT LIVE — locked out, extra prompts, no change, or no data. Then the deploy and persona groups of the ★ active baseline as a ladder — In / Not in / Not in this tenant — with HOW for every membership: direct, or nested via which parent group, read from the direct list plus one batch over the parents. The exclusion groups she is in are listed with the policies they take her out of, and one that bypasses an ENFORCED policy is named a standing bypass; who put her there is handed to ⚖ Compare users and 🕓 Change audit rather than read here. The policy table keeps the Off policies too (“becomes real when switched On”), says via what each policy reaches her — All users, a group with its path, a role, guest type, or EXCLUDED and by what — and carries her own blocked / interrupted counts from the log and, per report-only policy, the forecast. The sign-in half reads only this user's sign-ins, server-filtered so it never hits the record cap, or reuses the shared window when it is in memory and was not capped; the report-only forecast is her row from 🎚 Report-only impact, worst case first, with a report-only policy that evaluated none of her sign-ins shown as NO DATA rather than as safe. Registered MFA methods are an optional extra read behind a button. Buttons out to ⚖ Compare (with her added), 🧪 What-If (user filled in), 🔗 User or Group analyzer and a 🧪 Replay per stopped sign-in; Markdown brief and CSV. Same include/exclude resolution as ⚖ Compare users, same licence verdict as 🎫 Licence gap. Reads only" },
  toolWave:        { t: 37, v: "0.8.5", head: "\ud83c\udf0a Who is the wave to CA", chips: ["BETA"], folded: { into: "toolWhoIs", build: 25347 }, note: "25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. Compact group selector with member counts, restored log-source selection, stable tab layout. 0.8.2: one toolbar instead of two. The wave picker had its own sticky row above the controls row, and two sticky rows pin to the same offset \u2014 so the moment you scrolled, the chips you pick a wave from disappeared behind the search and the read button. Both rows are one row now, in the order every tool uses: search, the wave chips, the sign-in window, \ud83d\udd0e Read wave, the exports.;0.8.1: folded into T36 Who is … to CA (build 25347) as the A group subject. The wave read, the member table with its wrapping Flags chips and full screen, the risk read, the retired-control check and the forecast are untouched; openWave is unchanged and keeps its callers, including the member-name click that drills into the user subject;0.8: the Flags column is readable. Every flag used to render its whole list into ONE span joined with commas, and that span carries white-space nowrap, so it could not break anywhere: a member in five exclusions forced the column past the card, the table started scrolling sideways and the sentence ended at CA114 exclu. Nothing was missing, it just could not be read. Now it is a chip per policy in a cell that wraps, so the column grows DOWN and can never push the table wide again; the word exclusion comes off the chips and onto one count line (five chips said it five times), the chip colour carries the state instead of a parenthetical — red is a live bypass, plain is an exclusion on a policy that is not On yet — and the full sentence is on each chip's tooltip. Same change in all three list flags. Plus 👥 Members takes the whole window on a button: a state flag rather than the shared full-screen modal, because the wave rewrites its body whole on every filter click and a parked element would not survive the first re-render; Esc puts it back;0.7: 📵 the retired approved-client-app check across the wave — members going through the approved app, those with an app protection policy already seen, the red rows blocked the day the control goes; three tiles, the policies with their reach, the member table; in the export. 0.6.1: every card folds on its heading, remembered per card. 0.6: 🛡 READ IDENTITY RISK for the whole wave, on demand — one riskyUsers read per member (twenty to a batch, 404 = never flagged), joined to the risky sign-ins the members already have from the shared window and to the risk-based policies aimed at the wave: members at risk by level, remediated, risky sign-ins in the window, and which risk policy FIRES on whom as they stand. Before the read, a callout already names the members with a risky sign-in. Members open in 🕵 Who is Anna. Markdown export carries it. 0.5.1: policy numbers are the BASELINE's (CA012 from the policy name), not ENCA's running number — through the lookup shared with 🕵 Who is Anna 0.6. 0.5: a ■ Stop button on the read. A stop while the group is being read shows where it stopped and offers the read again — the wave is analysed from the whole group, so nothing partial is shown; a stop during the sign-in window keeps the group half and says the log half is missing. A running Graph call cannot be cancelled: the stop takes effect after the query in flight, and the line says so. 0.4: the hunting read says what it is doing. On a large tenant with Hunting + non-interactive a day is dozens of queries of a minute each, and the panel sat on “waiting for the first page” with an empty bar for the whole of it. Now every query is named — the day, the time slice, rows so far, slices halved for size — the bar moves inside a day, the clock runs on its own, and two tools asking for the same window at once share ONE read: the second says who is reading and joins it instead of reading the tenant twice. 0.3: picking a suggestion from the search box no longer reopens the list over the filled field — choosing from the list fires the same input event as typing, so the pick re-ran the search and the browser reopened the dropdown. 0.2: the Sign-in SOURCE segment — Entra sign-in log (interactive, capped at 10,000, AuditLog.Read.All), Defender hunting (the same interactive sign-ins from EntraIdSignInEvents through Graph runHuntingQuery, ThreatHunting.Read.All, no cap, 30 days) or Hunting + non-interactive (token refreshes and background client sign-ins too, which the Graph list never returns). Chosen once per tenant and shared by 🚦 🎚 🕵 🌊 with one cached window per source; the hunting read is one query per day so every response stays under the 50 MB cap, a day that hits the 20,000-row cap is said to be capped, and the table name falls back to AADSignInEventsBeta until its retirement on 19 October 2026. Needs Entra ID P2 for the table to be populated, through the shared window. 0.1: new, BETA — in production as build 309. The 🕵 Who is Anna to CA picture for a whole deployment group — the question before a report-only policy is switched On is “can THIS wave take it”, and the answer used to exist per policy (🎚 Report-only impact) or per user, never per wave. The picker offers the ★ active baseline's deploy groups and persona groups with their transitive member counts (a group the tenant lacks is greyed), or any group by name or id. Four tiles: policies TARGETING the group (enforced / report-only / off, plus how many reach members some other way), sign-ins Conditional Access STOPPED for members in the window, how many members would be LOCKED OUT if everything in report-only went live, and the quiet members. Then GO-LIVE READINESS per report-only policy that targets the wave: members with traffic, locked out (named), prompted, unchanged, silent — verdict Not yet / Friction only / Ready / No data, with silent members counted as no data and never as safety. The policy table says how each policy targets the wave (direct include, via a parent group, All users, or “reaches N members another way”) and how many members an exclusion takes back out and through which group. The member table carries how each got in (direct, via which child group, dynamic rule) and flags — standing bypass, two waves at once, blocked, would be locked out, no Entra ID P1, disabled — with filter chips, and every name opens 🕵 Who is Anna to CA. Reads are bounded by the GROUPS the policies name, not by the members: every referenced group (first 999 members) and the baseline's deploy / persona groups are read once, plus the directory roles, and every member is resolved against every policy through WhoIs.stateFor, the same function T36 uses, so the two tools cannot disagree about a member. Members are read transitively, first 500; the sign-in half is the shared window. Markdown report and a CSV of every member. Reads only" },
  toolSpGap:       { t: 39, v: "0.3.0", head: "\ud83e\udee5 Apps with no service principal", chips: ["BETA"], note: "0.3.0 (25381, Mihai: expand and collapse per item and global): FOLDED ROWS. One line per app — name, sign-ins, verdict, and the counts of what the three policy columns hold (1 would · 9 may · 0 excluded by · newest sign-in) — that opens on click to the full row: the would / may / excluded-by pills and the newest sign-in laid out as four columns. ⊞ Expand all and ⊟ Collapse all above the table set the default for every row; a click on a row is an exception to that default, so Expand all then one click closes just that one. The state survives a filter, a search and a rescan. Same click as 🚦 Sign-in failures' per-policy rows. 25370: local result search suggestions; matching before the 60-option limit; no extra Graph requests. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. 0.2.1: the verdict chip stays in its column — the Once it exists column is wider, the chip may wrap there, and a cell clips instead of running into the next one. 0.2: the table is the list table every plain list in ENCA uses, not the policy-matrix table it borrowed — padded cells, left-aligned headers, the app id in monospace under the name, policy pills that wrap, right-aligned sign-in counts, and the box is as tall as its rows instead of a 280-pixel minimum drawn over empty surface; seven columns scroll sideways on a narrow window rather than squeezing the App column. 0.1: apps that signed in over the last 30 days with no service principal in the tenant (auditLogs/signInEventsAppSummary diffed against servicePrincipals) — invisible to the CA app picker, reached only by All resources and only once they exist. Per app: the What-If verdict for an All-users sign-in the moment it exists (would apply with grant, may apply with the undecidable condition, or nothing), the policies already excluding the id (phantom exclusions), and on request the newest sign-in from the shared window as evidence. Five tiles, chips, search, Markdown + CSV. No generated PowerShell. Idea from Jhope188's CA Policy Analyzer v1.17.0, rebuilt on the 🧪 engine" },
  toolSessionCtl:  { t: 38, v: "0.6.4", head: "\ud83d\udec2 Session controls", chips: ["BETA"], folded: { into: "toolSignins", build: 25339 }, note: "25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. 0.6.2: folded into T17 Sign-in log (build 25339) as the Session controls tab, hidden on the production host by the same isProdHost test the BETA ribbon uses — the carve-out in the promotion port is a tab guard now instead of a deleted tile. The hunting read, the slicing, the stop button and the schema panel are untouched;0.6.1: when the sign-in window fails after the Defender hunt succeeded, a ↻ Read the sign-in window again button re-reads only the log and keeps the minutes of hunting already done; the note says the reason in one line — a 502 from Microsoft's gateway now reads as that, not as a page of nginx HTML — and Graph retries 502 like 503/504 before giving up. 0.6: a ■ Stop button on the read. A stop during the Defender hunt keeps the slices already read and renders them as a PARTIAL window, named as such in the notes, without reading the sign-in window; a stop during the sign-in read keeps the Defender half and says routing is missing. The stop takes effect after the query in flight — a running hunting query cannot be cancelled — and the line says so. 0.5: the hunting read says what it is doing. On a large tenant with Hunting + non-interactive a day is dozens of queries of a minute each, and the panel sat on “waiting for the first page” with an empty bar for the whole of it. Now every query is named — the day, the time slice, rows so far, slices halved for size — the bar moves inside a day, the clock runs on its own, and two tools asking for the same window at once share ONE read: the second says who is reading and joins it instead of reading the tenant twice. 0.4.1: the filter box no longer reopens its suggestion list on every keystroke and every pick — the list is rewritten only when the result changes. 0.4: no longer forever. One hunting query over a day of CloudAppEvents on a large tenant scanned millions of rows with a full-text AuditSource test and a sort, and the panel showed a spinner with no number. The window is read in 4-hour slices now, each its own query with a 2-minute limit — a slice that runs out of time is halved down to 30 minutes and then reported as skipped — with per-slice progress; the AuditSource test is an exact match and top replaces order-by + take. 0.3: the filter box suggests as you type — the users, apps, files, Defender policies and Conditional Access policies in the current result, labelled by kind — and the window gains 1-hour and 4-hour ranges next to 24 hours, 7 and 30 days, for checking a block that just happened; the hunting query reads hours below a day. 0.2: the four tiles are filters. The number sets the table it counts — policies with a session control, policies that routed a session, blocked activities, everything Defender acted on — and the counts under each tile narrow further: App Control / other session controls, logins logged, every event read, protected / step-ups / audited / unmatched. The chip strips gained a “Routed a session” policy filter to match, and the page scrolls to the table the tile filtered. 0.1: new, BETA, only here. What a session control actually DID. The Entra sign-in log stops at “policy applied — Conditional Access App Control”; the download that was blocked, the file that was labelled on the way out and the step-up that fired happen inside the session and are written by Defender for Cloud Apps, so “is CA308 blocking downloads” had no answer in anything ENCA read. Two sources, one join: Defender advanced hunting through Microsoft Graph — POST /security/runHuntingQuery over CloudAppEvents filtered to the session / access control audit source, delegated ThreatHunting.Read.All asked on the click, same host and MSAL client as every other read, 30-day retention, 5,000 events per read — and the Entra sign-in window 🚦 / 🎚 already share, where a sign-in whose applied policy carries a CloudAppSecurity session control is the ROUTING event. Joined on user, app and the newest routing sign-in within 8 hours (a user-only fallback is labelled; no match is shown as no match, never guessed). Four tiles, then per Conditional Access policy with a session control: state, the control (App Control monitorOnly / blockDownloads / mcasConfigured, sign-in frequency, persistent browser, token protection, CAE, app-enforced restrictions, Global Secure Access), sessions routed, what Defender did behind it, the Defender policies matched, and a verdict — Acting, Watching, Monitor only, Routed nothing acted, Nothing routed, Off, Report-only — with the reason in words. Then every Defender event with its routing policy, filter chips and search, and the Defender session policies seen with the CA policy that routes to each or the warning that none does. The activity schema is read tolerantly on purpose: which ActionType a blocked download carries and where the matched policy sits in RawEventData is documented nowhere and differs per app, so the classifier works on words and a schema panel lists the action types and raw field names actually seen — a block that renders as plain Activity is the signal to send that list back. A tenant whose hunting schema lacks AuditSource gets a wording-only fallback query and is told. The Monitor-only callout is derived from the policy, not typed. Reads only" },
  toolCompare:      { t: 18, v: "1.0.5", head: "\u2696 Compare users", folded: { into: "toolWhoIs", build: 25347 }, note: "25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. Same compact introduction and stable tab position as the other subjects. 1.0.2: folded into T36 Who is … to CA (build 25347) as the Compare users subject. The resolver, the side-by-side assignment matrix, the group and role membership diff and the optional What-If scenario per user are untouched; openCompare is unchanged and keeps its callers;1.0.1: picking a suggestion from the search box no longer reopens the list over the filled field — choosing from the list fires the same input event as typing, so the pick re-ran the search and the browser reopened the dropdown. 1.0: two or more users side by side: per-policy assignment (included / excluded and why / not targeted) with differences flagged, group and role membership diff, optional What-If sign-in scenario evaluated per user, differences-only toggle, Markdown export — out of BETA" },
  toolAudit:        { t: 16, v: "1.9.1", head: "\ud83d\udd53 Change audit", chips: ["UPDATED"], note: "25408: the results list and the detail pane each scroll on their own, pinned under this screen's toolbar. 25406: Shared list/detail workspace with native actions and flat icons. 25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25370: local result search suggestions; matching before the 60-option limit; no extra Graph requests. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. 1.7: THE HOST of what-moved. T28 Drift watch is folded in as the Snapshot file tab and the tile is Changes. Audit.diff was already the one engine — drift.js imports it from here — so the two tiles were two doors onto one question asked of two sources: the Entra audit log, which stops where your licence retention stops, and a snapshot file, which does not. The two bodies are deliberately NOT merged: a rolling timeline of who edited what and a two-point comparison against a file you kept are different shapes of answer, and the tab strip is what says which one you are reading;1-, 4- and 24-hour incident windows plus the existing 7/30/90-day review windows; directory audit log of Conditional Access changes — policy, named location, authentication strength/context and terms-of-use edits with a field-level diff of what moved, actor and IP, kind/action filters, Markdown export, JSON snapshot export/compare, summary view — out of BETA" },
  toolImpact:      { t: 26, v: "2.2.0", head: "\ud83c\udf9a Report-only impact", folded: { into: "toolSignins", build: 25339 }, note: "2.2.0 (25380): the bucket read is a STREAM into ReportImpact.accumulator — nothing of the window is held in the tab (25378/25379 held every record and a large tenant's week killed the tab twice). The query runs once per report-only policy per day (readSignInsHunting opts.parts), the user rows are no longer grouped by app, client or OS (apps are a set on the row, per-app counts and the one sample denial per user × policy are their own small rows), the cap is 90,000 rows, and the store keeps each day in chunks of 4,000 appended slice by slice (IndexedDB version 2 — the old shape is cleared on upgrade). The device's held days stream into the accumulator first. 2.1.1 (25379): the first real run of 2.1.0 died twice — “Maximum call stack size exceeded” from got.push(...records) on a week of buckets (Safari's argument limit), then the tab itself (Safari error 5, out of memory) because hour × user × app × policy on a large tenant is millions of records a week. Buckets are now per UTC DAY (bin 1d) in the query, the store and the coverage; every large append is a loop; the window's start is floored to the day when the store is on; what the device holds is rendered FIRST (onPartial note “held”) and the read starts by itself when 💾 is on for the tenant. 2.1.0 (25378, R58): 💾 Keep on this device — with per-tenant consent the bucket read keeps its hours in js/signinstore.js (IndexedDB, memory fallback) and a later read asks Microsoft only for the missing settled hours plus the newest two (SETTLE_HOURS), which are re-read every time; a capped interval is shown, never kept; Rescan reads everything and rewrites; the coverage line says what came from the device. tools/report-impact-store.test.cjs: the second look reads 3.5 hours instead of 168. 2.0.0 (25377): on the hunting sources the forecast is read as BUCKETS — Signins.roBucketQuery summarises the report-only verdicts per hour × policy × verdict × user × app (plus the device facts the deny explanation is judged on) before they leave Microsoft; a day is one query, the sign-ins are never read. Same slicing, stride, priming and Stop as the row read (readSignInsHunting opts.query/shape/kind), its own cache (roCache) so 🕵 🌊 🛂 keep the rows cache. ReportImpact.build adds n per bucket record and takes the denominator from the per-hour sign-in counts; tools/report-impact-buckets.test.cjs proves buckets and rows give the same forecast. A hunting engine that refuses the query (semantic error) drops the tool to the row read for the session, with a toast. The Entra log keeps the row path. 1.6.0 (25375): the hunting read keeps the slice length that worked. Halving used to start over at 24 hours for every day — 63 failed queries for the 64 that returned rows on a tenant that needs 22-minute slices, half the hunting CPU quota spent on nothing. The stride shrinks on a halving, doubles after three easy slices, is kept per tenant and source in localStorage, and the first worker reads alone until a slice has landed so the other three start at the stride it found. Four workers instead of two. The progress line names the rows already back and the current stride instead of saying it is still waiting for the first response. 25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. 1.5.2: folded into T17 Sign-in log (build 25339) as the Report-only impact tab. Nothing about the forecast changed — same build, same per-policy and per-user views, same progressive rebuild as the days land, same export. openImpact is unchanged and keeps its callers; the tab is where the tile used to be;1.5.1: a report-only policy granting on Require app protection policy says under its verdict that the control cannot be evaluated in report-only — Microsoft documents it reports Failure there even where it passes once enforced — so its would-deny count is not evidence. 1.5: the forecast arrives AS THE DAYS LAND. After every finished day of the hunting read (every five pages on the Entra log) the verdicts are rebuilt from what is in hand and shown under a still-reading strip with the bar; a 40-minute read on a large tenant gives a first answer in a minute. ■ Stop keeps what was read and shows it as a partial window, said to be one, never cached as the whole. The header names the sign-in source. 1.4.2: the hunting read says what it is doing. On a large tenant with Hunting + non-interactive a day is dozens of queries of a minute each, and the panel sat on “waiting for the first page” with an empty bar for the whole of it. Now every query is named — the day, the time slice, rows so far, slices halved for size — the bar moves inside a day, the clock runs on its own, and two tools asking for the same window at once share ONE read: the second says who is reading and joins it instead of reading the tenant twice. 1.4.1: the search box no longer reopens its suggestion list on every keystroke and every pick — the list is rewritten only when the result changes. 1.4: the Sign-in SOURCE segment — Entra sign-in log (interactive, capped at 10,000, AuditLog.Read.All), Defender hunting (the same interactive sign-ins from EntraIdSignInEvents through Graph runHuntingQuery, ThreatHunting.Read.All, no cap, 30 days) or Hunting + non-interactive (token refreshes and background client sign-ins too, which the Graph list never returns). Chosen once per tenant and shared by 🚦 🎚 🕵 🌊 with one cached window per source; the hunting read is one query per day so every response stays under the 50 MB cap, a day that hits the 20,000-row cap is said to be capped, and the table name falls back to AADSignInEventsBeta until its retirement on 19 October 2026. Needs Entra ID P2 for the table to be populated. The header names the source and says when non-interactive sign-ins are in the verdicts — a report-only forecast that counts token refreshes is a different number, and it says so. 1.3: the verdict chips count what the SEARCH left, not the whole run \u2014 they used to keep claiming five would-block policies directly above the words \u201cno report-only policy matches the current filter\u201d, and in Per user they showed policy verdicts including a never-in-scope chip no user can carry. The box also searches the GROUPS a policy targets, suggests the names actually present (policies, their target groups, or UPNs) as you type, and an empty result now says which of the two controls emptied it and carries the undo; 1.2: a would-deny row shows the actual sign-ins behind it, the way \ud83d\udea6 Sign-in failures does \u2014 the controls the policy demanded, then the client, OS, location and device state of the sign-in itself, with the failure reason and error code when the sign-in also failed for an enforced reason. 1.1: a would-deny row says WHY \u2014 what the policy demands and what the sign-in brought (\u201cneeds a compliant device \u2014 device NOT compliant, Azure AD joined\u201d), as evidence rather than diagnosis, with an unregistered device distinguished from a non-compliant one; an interruption names the risk levels behind it (user risk low \u00d72, medium \u00d71) with user and sign-in risk kept separate and \u201chidden\u201d not reported as \u201cnone\u201d; the sign-in window is shared with \ud83d\udea6 Sign-in failures instead of being read twice; and the tool finally has a Help section. out of BETA. 0.3: 1-hour and 4-hour ranges — check a fresh staged policy against the last hour instead of a whole day. 0.2: live progress while the window is read — running sign-in count, page number and elapsed time with a bar toward the record cap, so a large tenant's multi-minute read visibly moves (and survives switching tabs). BETA — the go-live forecast for report-only policies, from the sign-in log: per policy, who would be DENIED, who is interrupted for an extra step and who passes unchanged (reportOnlyFailure / reportOnlyInterrupted / reportOnlySuccess, with out-of-scope as the denominator's remainder); per user, the combined effect of everything in report-only at once, worst case first; verdict chips (would block / prompts only / no change / never in scope / no data — a staged policy with zero traffic is listed too, as the answer that should stop a go-live), distribution bar, per-user drill-down, 1/7/30-day window, Markdown export" },
  toolSignins:     { t: 17, v: "2.7.2", head: "\ud83d\udea6 Sign-in failures", note: "2.7.2 (25428, Mihai: the tab crashes on Hunting + non-interactive): A CEILING ON WHAT THE TAB KEEPS. HUNT_CAP is a cap per QUERY \u2014 20,000 rows, and a slice that reaches it is halved and both halves read, so one day can legitimately be 96 slices of 20,000. Nothing bounded the TOTAL. On Hunting + non-interactive the enforced read is dominated by legacy-protocol blocks of service accounts retrying every few seconds: hundreds of thousands of rows, every one shaped into a record and kept, and the tab died \u2014 the same death T26 had at 25379 before its read became a stream. readSignInsHunting now stops at HUNT_ROW_MAX (50,000) when it KEEPS its rows, reports ceiling:true, and the window is labelled \u201cstopped at 50,000 sign-ins \u2014 more than this window holds in the browser\u201d instead of the row-cap sentence, which is a different reason and asks the reader for something different. A streaming read (opts.onRows \u2014 T26\u2019s buckets) is exempt: it holds nothing. Two allocation fixes went with it. Rows are pushed in a loop, never out.concat(recs) \u2014 quadratic, and the intermediate arrays are allocated while the tab already holds everything read so far: 400,000 records in 500 slices measured 165 ms by concat against 6 ms by push (node 22, tools/ bench, not committed) \u2014 nor push(...recs), which is Safari\u2019s argument limit (25379). readSignInWindow finds oldest/newest in one pass instead of map+sort over the whole window. Signins.build also sorts ISO timestamps with < rather than localeCompare: measured 15 ms against 19 ms for 50,000 on node, so a tidy-up and the right comparison for an instant, NOT a fix for the crash \u2014 the ceiling is. Shared by \ud83c\udf9a \ud83d\udd75 \ud83c\udf0a \ud83d\udec2 through readSignInWindow; tools/hunting-stride.test.cjs covers the ceiling, the exemption and the caller override. 25408: the results list and the detail pane each scroll on their own, pinned under this screen's toolbar. 25406: Shared list/detail workspace with native actions and flat icons. 2.6.0 (25381, Mihai: include what a user used to sign in — the user must use phishing-resistant MFA but is using a password): SIGNED IN WITH. Every failed or interrupted sign-in now says what the person authenticated with — the portal's Authentication Details tab, read from the record's authenticationDetails: Password — Phishing-resistant MFA required, not provided (MFA required in Azure AD), or Password + Microsoft Authenticator — MFA satisfied, or MFA by a claim already in the token. A password where MFA or a strength was required is the gap that explains the failure without a policy change: it is red on the card, on the per-policy detail line, counted per policy (🔑 3 without the MFA asked) and in the header, and it has its own filter chip. The sign-in card lists the steps (✓ Password · Password in the cloud — Correct password [Phishing-resistant MFA] / ✗ (no method) — MFA required in Azure AD). CSV gains authRequired, authUsed, authGap; the Markdown export a Signed in with column. Hunting rows carry the requirement and no steps, and say so. 2.5.0 (25378): the shared sign-in source segment carries the 💾 Keep on this device button (R58) and its consent dialog; the button reads one state for every toolbar that mounts the segment. Rows for 🚦 🕵 🌊 🛂 are NOT stored yet — buckets only. 2.4.0 (25375): the shared hunting reader remembers its stride — see T26 1.6.0; the enforced-failures and per-user hunting reads keep plain day slices, they never needed halving. 25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. 2.2: THE HOST of the sign-in window. T26 Report-only impact and T38 Session controls are folded in as tabs, and the tile is Sign-in log. The three already shared readSignInWindow, logCache and one consent — the only sign of it on screen was a line saying the window had been re-used — so the fold takes away the second and third door, not a read. Each tab keeps its own toolbar (range, source, search, exports) because the three ask different things of the same records, and the strip is mounted into those toolbars rather than moving the screens into one panel. Also: the Report-only MODE of this tab now says outright that it lists individual sign-ins and points at the Report-only impact tab for the per-policy verdict — two things called report-only on one tool is the confusion the fold would otherwise have created;2.1: the hunting read is SLIM and TWO DAYS AT A TIME. On a 140-policy tenant every sign-in row carried 140 policy entries, 130 of them not applied — 30 KB of JSON per row that drove a 7-day read to 459 queries of 15-minute slices (40 minutes for 93,500 rows). The not-applied entries are dropped in the query with mv-apply; the report-only ones survive as a list of ids so out-of-scope counts stay exact; a row shrinks ten to twenty times and a day fits in one or two queries. Two days are read at once. Shared by 🎚 🕵 🌊 🛂. A schema that refuses the slim query falls back to full rows and says so on the progress line. 2.0.5: the hunting read says what it is doing. On a large tenant with Hunting + non-interactive a day is dozens of queries of a minute each, and the panel sat on “waiting for the first page” with an empty bar for the whole of it. Now every query is named — the day, the time slice, rows so far, slices halved for size — the bar moves inside a day, the clock runs on its own, and two tools asking for the same window at once share ONE read: the second says who is reading and joins it instead of reading the tenant twice. 2.0.4: the search box — picking a suggestion from the search box no longer reopens the list over the filled field — choosing from the list fires the same input event as typing, so the pick re-ran the search and the browser reopened the dropdown; the suggestion list is rewritten only when it actually changes. 2.0.3: the hunting source on a tenant without the table. A tenant whose hunting schema has no EntraIdSignInEvents (it needs Entra ID P2 to exist) fell through to the AADSignInEventsBeta fallback, which is gone too, and the error quoted the fallback's name — misleading. The fallback is now tried only when the error names the table itself, and when both names fail the message says what it is: no Entra sign-in table in this tenant's schema, needs P2, switch the source back to the Entra sign-in log. Applies to 🚦 🎚 🕵 🌊. 2.0.2: the hunting source survives a large tenant, second attempt. A 4-hour window with non-interactive sign-ins still failed on result size after slicing to 15 minutes — the policies JSON on every row is what weighs, not the row count. Two changes: a 15-minute slice that still exceeds the size lowers its row cap (20,000 → 10,000 → … → 1,000) and is reported as capped instead of failing the read; and Enforced on the hunting source now filters in KQL — CA failures and the interrupt error codes only — so it reads hundreds of rows where the full window is hundreds of thousands. Report-only still needs the whole window (that is where the report-only results are). 2.0.1: the hunting source survives a large tenant. A day of sign-ins, each row carrying its ConditionalAccessPolicies JSON, can exceed advanced hunting's response cap (“Query execution has exceeded the allowed result size”), which 2.0 reported as a failure. The window is now read in explicit datetime slices — a day at first — and a slice that fails on size, or comes back at the row cap, is halved and both halves read, down to 15 minutes; only a 15-minute slice that still hits the cap is reported as capped. The progress line says how many slices were halved. Same for 🎚, 🕵 and 🌊, which share the read. 2.0: the Sign-in SOURCE segment — Entra sign-in log (interactive, capped at 10,000, AuditLog.Read.All), Defender hunting (the same interactive sign-ins from EntraIdSignInEvents through Graph runHuntingQuery, ThreatHunting.Read.All, no cap, 30 days) or Hunting + non-interactive (token refreshes and background client sign-ins too, which the Graph list never returns). Chosen once per tenant and shared by 🚦 🎚 🕵 🌊 with one cached window per source; the hunting read is one query per day so every response stays under the 50 MB cap, a day that hits the 20,000-row cap is said to be capped, and the table name falls back to AADSignInEventsBeta until its retirement on 19 October 2026. Needs Entra ID P2 for the table to be populated. With non-interactive rows in the result the header counts become chips — interactive / non-interactive — that filter the list, the same chips sit in the filter strip, and each sign-in card says non-interactive. Enforced mode on the hunting source reads the shared window and keeps the failures and interrupts itself, since hunting has no server-side CA filter. 1.9: interrupt attribution narrowed by what the error code can actually demand — 50074/50076/50072/50079/500121 attach to the applied policies with an MFA or authentication-strength control, 50097 (device authentication) to compliant/joined-device or sign-in-frequency controls (enforcing SIF in a browser means authenticating the device for the session's auth timestamp), 50158 to terms of use; a 50097 next to an MFA policy and a SIF policy now names only the SIF policy. No matching control falls back to every control-bearing applied policy rather than dropping the record. 1.8: enforced mode also gathers the sign-ins Conditional Access INTERRUPTED — abandoned MFA prompt, MFA enrolment, device auth, terms of use. Graph has no 'interrupted' CA status (those records carry 'success' plus an interrupt error code), so a second server-filtered fetch on the interrupt codes (50072/50074/50076/50079/50097/50158/500121) is deduped into the failures and each interrupt is attributed to the applied policies that imposed a control; interrupted badge per sign-in, Blocked/Interrupted filter chips, counts in the header, per-policy table and Markdown report, result column 'interrupted' in the CSV. 1.7: in report-only mode the sign-in window is shared with \ud83c\udf9a Report-only impact \u2014 byte-for-byte the same Graph read, so switching between the two no longer costs a second multi-minute pass over ten thousand records. \u27f3 Rescan always re-reads the tenant, and enforced mode keeps its own server-filtered query. 1-hour and 4-hour ranges for incident triage;search box suggests UPNs — the users and apps in the current result first, then the directory;Sign-ins (per sign-in) is the default view; usable on a phone (full-width search, swipeable policy chips, tighter cards); out of BETA; policy names open the policy card (as in List Policies); sticky policy label while scrolling an expanded policy's sign-ins; sign-in log × Conditional Access verdicts — sign-ins a policy failed (enforced) or would have failed (report-only, client-filtered and capped), grouped per policy with distinct users, affected apps and unmet grant controls; per-policy chips, user/app/IP search, 1/7/30-day window, one-click replay of a logged sign-in in What-If, CSV export (one line per sign-in × failing policy) and Markdown report" },
  toolBaseline:     { t: 10, v: "2.9.1", note: "2.9.1 (25467, Mihai: t10 fix the box layout): THE CATALOG CARDS, LAID OUT. Three faults in each 🧱 Update the catalog card. The action row carried class row, which has a rule only inside .modal, so it had justify-content, gap and flex-wrap written inline and no display:flex for any of them to act on — the tick, the reason field and Hold fell into plain flow, the field never stretched (its hint was cut to a few words) and sat flush under the label, so its focus ring landed on the label text. The reason field was an input styled as a button (class btn), so it read as a second button. And the policy name was a flex item at its default min-width, which can hold a card wider than its column on a narrow window. Now: bl-cardact is a real flex row — tick, or, a proper text field that takes the remaining width, Hold — and bl-cardname and the catalog/tenant lines may break anywhere. Rendered before and after in Chromium: the collision and the cut hint are gone at 1012px, and at 560px and 390px nothing overflows the card. 2.9 (25463, Mihai: when in the baseline page on the baseline tenant, I want to select export baseline, options per persona and Dependencies): THE BACKUP EXPORT, FROM THE BASELINE PAGE. Not a second exporter — the button hands the whole policy set to the SAME runBackup(); backupScope() narrows it to the persona baseline as it already did, and a persona chooser narrows that. The zip, the dependency read and the MigrationTable are untouched, so there is one implementation of the export and one place a fault could live. The chooser offers only personas the tenant actually has, with counts, and a — no CA number row when some policy carries none; Dependencies is ticked on open, because taking a baseline somewhere else without its groups, strengths, locations, contexts and terms of use is not taking it. FIXED ON THE WAY: with no persona ticked the panel used to keep the PREVIOUS count and leave Download live, so it would have exported the last set rather than the empty one — it paints zero and disables the button now; without the chooser the old toast stands. Gated isBaselineTenant() and not demo, the same test the 25436 catalog button uses. 2.8.0 (25436, Mihai: a button in the baseline tenant to check which policies got updated): \ud83e\uddf1 UPDATE THE CATALOG FROM THIS TENANT \u2014 baseline tenants only, never demo. The baseline tenant is where the catalog is AUTHORED, so this runs the comparison the other way round: not \u201cis the tenant behind the catalog\u201d but \u201cwhat has the catalog not caught up with\u201d. Mihai asked for changed \u2192 export \u2192 import; that was mocked against this and he picked this. Import writes to a TENANT, and baselineData.js is a source file, so an export/import round trip leaves the last mile manual and carries none of the judgement. THE RULE IT IS BUILT ON: COMPARE STRUCTURE, GENERATE PROSE. The catalog\u2019s strings were written by a one-off generator that is NOT in this repo, so if the diff string-compared against prose re-derived here, one comma would report all 105 policies as changed. entryDiff normalises both sides \u2014 group order, condition order, the bullet and minus decoration, line-break markup and markdown emphasis all ignored, which is exactly the false-positive pile the 2026-08-20 header complains about. vmToEntry is used only for the OUTPUT. Baseline.compare judged on the VERSION IN THE NAME and never on content, so a policy edited without a version bump read as ok; this catches those. HOLDS are keyed by diffSig, the signature of the difference they were made about \u2014 so the 58 dropped exclusion groups stay held, and a later DIFFERENT change on one of them reopens by itself and is marked REOPENED. Kept per tenant and catalog in localStorage. DRIFT SELF-CHECK: every policy the diff calls unchanged is a free test of the serialiser \u2014 its entry should come back identical to the catalog\u2019s. The panel reports how many do not, because that is cosmetic, not wrong, and you should know before pasting. Gone-from-the-tenant is reported and NEVER removed: deleting a baseline policy is not a decision this makes. Output is a report (download/copy), never a write to the repo or the tenant. tools/baseline-catalog.test.cjs: 18 tests. UI NOT RUN IN A BROWSER, and never run against the real CloudFellows tenant. 25397: a catalog that defines two policies on ONE CA number is matched one policy to one policy. The live read of the repository keeps duplicate numbers rather than hiding them, and release 2026.6.1 numbers both the AnyPlatform and the iOS/Android copy CA005 (CA006 the same way); the comparison dropped the whole number as soon as the first row had matched, so the second read not present in this tenant while its policy sat two lines above it, and Import counted it among the policies to create. Rows whose exact name is in the tenant claim first, so the pairing does not depend on the order Graph returns, and the warning that two policies share a CA number is kept for copies the catalog does not account for. 25386: the leftovers list after a baseline switch no longer offers a CAD-SEC-U-DG deploy group or an E-Admins group (Emergency_Access1, Emergency_Access2, CAB-SEC-U-BreakGlass): every baseline uses them, so they are no leftover of the old one. 25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25370: local result search suggestions; matching before the 60-option limit; no extra Graph requests. 2.7: a Deployment guide tab. T29 Baseline guide only ever answered one question — how do I deploy this baseline — and answered it by reading the tenant and linking seven other tools, so it sits in the tool that holds the baseline it describes rather than beside it. Beta-only, hidden on the production host by the same isProdHost test the BETA ribbon uses;2.6: one tile, both catalogs. T11 Baseline (Joey Verlinden) was a second tile calling openBaseline('joey') against this screen, which has had a catalog picker in its toolbar since 2.0 — so the tile was a shortcut to a segment control one click away. Folded: the picker is the way between the two catalogs, the tile opens on the tenant's ACTIVE catalog rather than always CloudFellows, and openBaseline('joey') is unchanged for its six callers;2.5.1: the card reads its numbers out — how many of the catalog's own policies are here, what a number clash is and whose policy took the number, whose the not-in-baseline rows are — and every count chip carries the meaning as a tooltip; the CloudFellows card says by match with both counts too, and 📌 Keep, when nothing is saved; on a tenant holding both baselines the exact-named policy now wins a shared CA number (CloudFellows' CA000 was passing as Joey's), and an unversioned catalog counts only the exact name as present, a same-number other name is a clash;2.5 (R36.1): the count chips on the summary card are the filter; a tenant with no saved choice gets the baseline it holds most of by name as the ACTIVE one for the session (★ by match, 📌 Keep saves it, an explicit choice is never overridden); the CloudFellows E-Admins policies are expected under every catalog as a shared 🚨 section instead of six not-in-baseline rows; an active catalog with missing policies opens on Missing; 📥 Import baseline on Joey Verlinden starts from the live repository read — policy files, Config/Groups, Config/NamedLocations — with the gap ticked, no zip;2.4 (R36): 🧹 What the other baseline left behind — its groups, persona units and policies with a verdict each; deletes only the unreferenced, empty and Off, units first, behind a typed DELETE;2.3 (R36): the ★ button runs a dry run first — expected groups, vaults, routing changes and conventions, read from the tenant — and only then offers the switch;2.2 (R36): the ★ active baseline — the summary card says which of the two baselines this tenant works against and a button switches it, kept per tenant; looking at a comparison never changes it;2.1: \ud83e\uddf7 Update pre-requirements \u2014 one click for a configuration snapshot, a full backup with dependencies and Markdown documentation, before the baseline is changed; 2.0: one view, the table — in both catalogs. The Cards/Table toggle defaulted to the table for CloudFellows and to cards for the community catalogs, so the same screen answered the same question two different ways depending on which catalog you had clicked, and reading the two baselines side by side meant comparing a table against a wall of cards. A baseline comparison is a row per policy with a status.;1.9 (R35): the bundled catalog is published as the CloudFellows baseline — display name only; the catalog id (limonit) and the CAB-SEC / CAD-SEC group names are unchanged, so stored comparisons and Drift snapshots still match;CloudFellows catalog, table view, number-clash detection, collapsible personas, catalog revision 2026-08-20, refresh, on-screen gap report" },
  toolBaselineJoey: { t: 11, v: "2.0.2", folded: { into: "toolBaseline", build: 25338 }, note: "2.0.2: folded into T10 Baseline (build 25338) — the tile is gone and the catalog picker in the Baseline toolbar is the way to this catalog. Nothing about the catalog changed: the live repository read, the bundled 2026.6.1 fallback, the naming contract and the star active-baseline switch all still live on its own summary card;2.0.1: the live read decodes the repository's UTF-16 policy files;2.0 (R36): a first-class baseline — his exclusion groups as templates, his personas as vaults, an exact-match naming contract, and the catalog read LIVE from his repository once per session (latest release and the commit it read) with the bundled snapshot as a stated fallback;1.2: renders as a table, the same as the CloudFellows catalog — it used to open as cards, which is why the two baselines could not be read side by side.;Joey Verlinden catalog 2026.6.1, verified against commit 38469a4" },
  toolMsLearn:      { t: 7, v: "2.15.1", head: "\ud83d\udcd8 MS Learn: documented exclusion checks", folded: { into: "toolGapCheck", build: 25342 }, note: "2.15.1 (25490, Mihai: shouldn't the Learn get a scan like Bypass?): IDLE UNTIL ASKED. The tab ran by itself on every open, and since 25469 and 25472 that is a real read — strengths, cross-tenant access settings (default and every partner), CA settings, authentication methods, the convention groups and a guest $count per included group (up to 80). openMsLearn now shows a ▶ Run checks prompt listing exactly what it reads, like 🛡 Bypass & Swiss cheese; mlScan() does the run. The result stays across tab switches (mlKey as before); the Include Off tick re-runs only when a result exists; ⟳ Refresh re-reads the tenant AND re-runs. 2.15.0 (25489, Mihai on the shared-device matrix: shouldn't those blocked ones be mentioned below, with a why and how to fix — also for guests?): EVERY BLOCKED OR TRUST CELL NOW HAS A FINDING. Walking every guest-matrix control against the checks showed one gap — MFA for B2B direct connect without inbound MFA trust — now dc-mfa-needs-trust (denies; silent when trust is on for every tenant or direct connect is blocked inbound). For shared devices only MFA, sign-in frequency, the device-code block and Surface Hub's grants had findings, and only on All-users-All-resources policies: shared-device-unsupported (denies) reports, per policy that reaches the resource accounts, every control DEVICE_SUPPORT marks not supported, per device family, leaving out what the older checks already say (no double report). Its remediation splits on how the policy reaches them: through All users → exclude the shared-device group (the Fix adds it); by including the group → it is their own policy, so drop the control — no exclusion fix is offered there. Both matrix notes say each cell is explained below. Four tests. 2.14.0 (25485, Mihai: yes build that one also — the shared-device row for the matrix): 🖥 THE SHARED-DEVICE MATRIX, below the guest one. Rows: Teams Rooms on Windows, Teams Rooms on Android / phones / panels, Surface Hub. Columns: the controls demanded by the loaded policies that reach their resource accounts — All users unless the policy excludes the shared-device group (ctx.sharedDevices, the convention group the checks already find), or a policy that includes that group — and only when it targets All resources or an app the devices use (Office 365, Exchange, SharePoint, Teams, Intune enrollment, Device Registration); a platform condition picks the family. Verdicts come from DEVICE_SUPPORT, typed from Microsoft's table (Supported Conditional Access and Intune device compliance policies for Microsoft Teams Rooms and Teams Android Devices, updated 6 Jul 2026) and the Surface Hub page: ok, prompts (Android MFA — supported, but Microsoft says do not enforce it for seamless sign-on), blocked, and ? for what a device's documentation does not cover (Surface Hub documents only the grant controls) — never a guessed ok. deviceDemands adds risk remediation, token protection, customised CAE, disabled resilience defaults, insider risk and a device-code block to the guest matrix's controls. A cell sets idFilter and opens 🗂 Policies, like the guest matrix. Four tests. 2.13.0 (25475, from the CloudFellows baseline export Mihai asked to have checked): A TEMPORARY ACCESS PASS IS NOT A GUEST METHOD, AND A BLOCK IS COVERAGE. RESOURCE_OK_METHODS carried temporaryAccessPass, so a strength like Phishing-resistant MFA + TAP looked satisfiable by any guest and the five guest-admin policies CA502/503/506/507/508 produced nothing; Microsoft's external-users table lists TAP in neither column and the security-info template says a TAP does not work for guests. comboUsableHere / comboUsableAtHome replace the home-only test; a strength with no combination a guest can complete anywhere reads blocked in the matrix and says not here and not through trust. MFA_EQUIV_SIGNATURE no longer treats a TAP as the Require MFA signature — it read PR + TAP as equivalent to Require MFA and would have advised a downgrade. ext-type-no-mfa: fullBlock / blockedBy count an UNCONDITIONAL All-resources block that reaches a type as coverage (CA099 block non-persona shuts out other external users, so CA400 missing them is no gap) and name it in the finding; a block with a location, platform, client-app, risk, device or auth-flow condition does not count. Three tests. 2.12.0 (25472): GUESTS REACHED THROUGH A GROUP. A B2B guest is a directory object and can sit in any group, so a policy that includes a group of guests (guest admins, a partner group) reaches them as surely as one naming the user type — and every guest check skipped such a policy, because extScope only read the type selection. readGuestGroups in app.js counts, per group included by a policy that does not already reach every user (MSLearn.guestGroupIds), the transitive members with userType Guest ($count, 4 at a time, capped at 80, partial when a read fails or the cap is hit); extScope adds B2B collaboration guests with the group named and its count as the reason, unless the policy also excludes that group or the type. The count cannot tell a B2B guest from a local guest created as userType Guest, so the finding says members with userType Guest. A group of guests is never ALL guests, so mfaReaches asks without it (extScope noGroups) and the no-MFA gap finding still names the type. The summary says how many groups were followed and when the read was partial. Four tests in tools/mslearn-audit.test.cjs. 2.11.1 (25471, the open items of the audit, Mihai: go ahead with building): TOKEN PROTECTION EXCLUDES ONLY THE ENTRA-JOINED DEVICES. Learn lists Entra-JOINED Cloud PCs, AVD session hosts, Power Automate hosted machines and Azure VMs as unsupported, and its own example rules pair each label with trustType -eq AzureAD. The rule the fix wrote had no trustType, so it also took hybrid-joined Cloud PCs and session hosts out of token protection, which supports them. TOKEN_PROT_DEVICE_RULE now pairs every label with trustType AzureAD (parenthesised, systemLabels still -contains) and adds MicrosoftPowerAutomate; the previous rule is the first fallback, because it is the one known to be accepted, then SecureVM alone. token-prot-devices also reports the opposite fault: a rule that names the labels without trustType is over-broad. remediationParts: Change / Only Entra-joined / By hand (Autopilot self-deploying by enrollmentProfileName, Surface Hub and Teams Rooms by resource account). THE NEW RULE HAS NOT BEEN ACCEPTED BY GRAPH YET — the fallbacks exist for exactly that. 2.11.0 (25469, Mihai: re-check all the logic behind T07 and T08, they need to be rock solid, the remediations need to be logical for a human, and what has not been caught): AN AUDIT, NOT A FEATURE. THE TRUST ANSWERS WERE READ FROM THE WRONG LIST. Every guest check that depends on cross-tenant trust read only the partners flagged as service providers — never the DEFAULT inbound trust, which decides for every organisation without its own row. In a tenant with no CSP the list was empty, every partner trusts was vacuously true, and a compliant-device policy reaching every B2B guest was reported as fine; the guest matrix said ok. Graph.crossTenantTrust() now reads the default and every partner, a partner whose flag is null INHERITS the default, and guestTrust() answers true / false / not known with the sentence to show. Three tests had pinned the old behaviour and were rewritten. OTHER DEFECTS: Windows Cloud Login pointed at Azure Windows VM Sign-In (372140e0) instead of 270efc09, so a correct token-protection policy was flagged and the fix wrote the wrong app; the approved client app check still said March 2026 and that the control stops being enforced — since 30 June 2026 a policy carrying it is READ-ONLY and still enforced, and the transition pattern (approved OR app protection) is frozen too, so it is reported now with a four-part remediation; severity Low sorted as NaN, rendered unlabelled and could not be filtered; every user-risk policy reaching guests was called a lockout, where only password change, risk remediation or block are; the Defender mobile exclusion was asked of legacy-auth, device-code and desktop-only blocks the app never meets. NEW CHECK ext-type-no-mfa: an external type that no MFA policy on All resources reaches, anchored on the guest MFA policy where the fix belongs, with a fix that adds only the missing types; B2B direct connect is left out while it is blocked inbound, and when it is open the remediation warns that MFA without inbound MFA trust blocks it. It is what the 25468 catalog revision exposed: CA000 excludes every external type, CA400 names four. Fixes now receive the finding result as a third argument. tools/mslearn-audit.test.cjs (9). 2.10.0 (25460, Mihai: but the check clearly says to exclude these users, I am confused): WHICH WAY IS THE POLICY WRONG. Four external-identity findings open with EXCLUDE THE GUEST AND EXTERNAL USER TYPES and two now say EXCLUDE NOTHING; read as six instructions about guests they contradict each other, and the screen never said which was which. They are opposite failures. A control the identity CANNOT SATISFY denies them access — too strict, and the fix takes them out of scope; a control that is NOT APPLIED to them lets them through asking nothing — too loose, and the fix brings a requirement that reaches them, where excluding people the policy already asks nothing of would change nothing. Every classified finding carries a badge on its head (🚫 Blocks them / 🕳 Misses them, never the severity colour, which answers a different question) and one line at the top of its detail saying what that means for the people in it. The classification lives in ONE table, EFFECT, so both families can be read together and a new check cannot quietly join neither; a check that is not in it shows NO badge, deliberately — dc-unsupported-control ends in decide deliberately and sp-exclusion-incomplete covers identities you meant to exclude, which is a third thing, and claiming a verdict the docs do not support is the one thing these checks do not do. The gap finding also names itself as the exception in its own Exclude line. Tests assert the classification against each check's actual remediation, so the badge cannot drift from the advice. 2.9.0 (25459, Mihai on a policy using the built-in Multifactor authentication strength: the strength is allowing more, so the conclusion of the check is wrong): ONE VERDICT WAS TWO. The guest auth-strength finding judged every strength the same way and told you to keep it and add a second policy — advice that only fits a strength asking MORE than Require multifactor authentication does. Microsoft's built-in strengths table calls the MFA strength THE SAME SET OF COMBINATIONS THAT CAN BE USED TO SATISFY THE REQUIRE MULTIFACTOR AUTHENTICATION SETTING, and the Limitations section says the two controls cannot share a policy BECAUSE they are equivalent. So where the strength is no stronger than the grant control, adding a second policy is work for nothing: the answer is to SWAP the control on the policy that is already there. New check guest-auth-strength-swap-for-mfa, severity low, with an ordinary in-place fix (drop authenticationStrength, add mfa); the original guest-auth-strength-not-universal now returns null for those strengths and keeps the companion for the stricter ones, saying in its own words why it cannot be a swap there. isMfaEquivalent reads the strength's OWN allowedCombinations rather than an id: a password with a second factor, a federated combination or a Temporary Access Pass is the MFA-strength signature and appears under no other built-in, and a custom strength that admits a password is by that same table no stronger than Require MFA. With the strengths unread the swap check says nothing rather than guessing, and the conservative finding stands. The two are asserted mutually exclusive over four strength shapes in tools/mslearn-guests.test.cjs. 2.8.0 (25458, Mihai on the guest auth-strength finding: it is not clear what to exclude and what to create): A REMEDIATION WITH TWO ANSWERS, AND THE POLICY IT ASKS FOR. The check said to keep the policy for Entra-authenticated externals and add a second one for the rest, which reads as an instruction to carve those identities out — and that carve-out cannot be written: no Conditional Access condition names the identity provider a guest signed in with, and the six external user types do not separate an Entra-authenticated guest from a Google-federated one. remediationParts renders as EXCLUDE (nothing, and why) / CREATE (one policy, its exact scope and control) / WHY TWO (Microsoft does not allow Require multifactor authentication and Require authentication strength in one policy, and every applicable policy must be satisfied, so both reach every guest). New COMPANION hook beside fix: a fix edits the offending policy and shares one draft per policy, a companion builds a SECOND policy from the raw one and never touches the original — sharing the draft would have let this check strip the strength another fix had just kept. The companion carries the scope unchanged, grantControls Require multifactor authentication only, no session controls (the original still applies them), state Off, and is NAMED AT THE NEXT FREE CA NUMBER IN THE ORIGINAL RANGE, not bumpVersion: a bumped version is what Housekeeping reads as a supersession and Duplicates as a copy to merge, and this policy lives beside the original for good. A name off the convention gets one in words instead of a forced shape, and a staging prefix is never carried into it. Marked companion in the Fixes tab, which now says how many of the prepared policies go BESIDE theirs rather than replacing them. Five tests in tools/mslearn-guests.test.cjs. 2.7.1 (25434, Mihai: leaving the tab and coming back does a sort of refresh): THE RESULT SURVIVES A TAB SWITCH. openMsLearn ran the whole pass on every open \u2014 authenticationStrengthPolicies, serviceProviderPartners, readCaSettings, readAuthMethods, 30 checks over every policy, buildFixes and existingAppIds \u2014 and reset mlTab, mlFixes, mlMatrix, mlFilter and mlExpanded on the way in. Its three sibling tabs in \ud83d\udee1 Checks all had `if (result) { render(); return; }`; this one never did. It has one now, but KEYED: mlKey === mlReadKey() over [tenantId, isDemo, policiesReadAt, mlDisabled.checked]. A bare presence check is safe for the siblings because they wait for a Run button; this tab runs BY ITSELF on open, so a result from another tenant, another policy snapshot or the other scope must not be shown as the current one\u2019s. runMsLearn stamps the key when the result lands; an empty tenant clears it. \u27f3 Refresh still re-runs (loadFromGraph moves policiesReadAt), and so does toggling Include Off. tools/checks-tab-cache.test.cjs asserts the guard structurally across all four tabs \u2014 the path has no unit harness, and the shape is what stops the next tab repeating it. 2.7.0 (25433, Mihai: check guest accounts and their required exclusions against the policies \u2014 if they cannot satisfy passkey they need excluding): GUESTS & EXTERNAL USERS \u2014 six checks and a matrix, built ONLY from the two tables Microsoft publishes for external identities (the control support table in external-id/authentication-conditional-access, and the auth-strength method table in concept-authentication-strength-external-users). Both were fetched and read for this build, not recalled. THE CHECKS: guest-auth-strength-unsatisfiable (every allowedCombination needs a HOME_ONLY_METHODS method \u2014 fido2, windowsHelloForBusiness, x509*, deviceBasedPush, hardwareOath \u2014 so the built-in Phishing-resistant and Passwordless strengths cannot be met in the resource tenant; distinguishes trust-not-configured from trust-not-read from trust-on-but-verify-the-home-tenant); guest-auth-strength-not-universal (strength does not apply to email OTP / SAML / Google / MSA externals at all); guest-unsupported-grant and guest-device-grant-needs-trust (the sp-* pair generalised past service providers); guest-user-risk-blocked; dc-unsupported-control (ToU, SIF, persistent browser, app-enforced, CA App Control \u2014 supported for collaboration, NOT for direct connect). THE MATRIX: MSLearn.guestMatrix(raws, strengths, opts) + renderGuestMatrix, mounted above the findings in app.js. Types \u00d7 the controls the loaded policies demand; verdicts ok | trust | blocked | na with RANK precedence so the worst wins per cell; a control nothing demands of a type has NO cell (blank \u2260 fine); a cell click sets idFilter and opens \ud83d\uddc2 Policies. Same inputs as run(), so no extra read and no new permission. TWO RULES THAT KEEP IT HONEST: internalGuest (local guest) is EXCLUDED from every cross-tenant check and reads ok everywhere \u2014 it is an account in THIS directory with UserType Guest, so the limits do not apply, and treating it as external is the mistake that makes a guest finding wrong. And an excludeGuestsOrExternalUsers naming enumerated tenants does NOT take the type out of scope \u2014 it only reaches the tenants it names. extScope(p, want) generalises spScope; CROSS_TENANT_TYPES drops internalGuest and serviceProvider so the sp-* checks (which know the partner list) keep their cases. 30 checks, up from 24. tools/mslearn-guests.test.cjs: 18 tests. UI NOT RUN IN A BROWSER. 25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 2.6.1: folded into T08 Checks (build 25342) as the Microsoft Learn tab. The checks, the service-provider set, the cross-tenant read and the buildable fixes are untouched; openMsLearn is unchanged and keeps its callers;2.6: two user-risk checks — Require password change alone cannot remediate a passwordless user (medium, names the passwordless methods the tenant has on), and Require risk remediation cannot be satisfied by an external authentication method (high, only when the tenant has one enabled); the authentication methods policy is read once per load for them; neither check calls password change deprecated, because Microsoft does not;2.5: every Learn link re-verified (17 pages) — the token-protection known-limitations anchor moved to the Windows deployment guide; the platform check no longer says Windows-only: MDM-managed macOS / iOS are a preview, other platforms are blocked, Apple gets its own caveat;2.4: the All-resources-with-exclusions entry is rewritten for after the June-2026 rollout — medium instead of high, the full baseline scope set, the Learn page on enforcement for resource exclusions, and a tenant sentence from the Baseline scopes setting (enforced / DISABLED leaks today / placeholder excluded by design / not read);2.3 (R36): the canonical break-glass group is the active baseline's, the other name stays an accepted alias;five service provider (CSP / GDAP) exclusion checks, judged against the tenant's own cross-tenant access partners — inbound device trust suppresses the device finding, no partner skips all five; findings whose whole remediation is an exclusion are suppressed when the policy already carries it; create builds from the bundled group template; 22 documented checks, 16 buildable fixes, apply-in-tenant with service-principal creation and change report" },
  toolCis:          { t: 21, v: "0.6.4", head: "\ud83d\udcd0 CIS Benchmark alignment", chips: ["BETA"], folded: { into: "toolGapCheck", build: 25342 }, note: "25391: beta channel AND the CloudFellows tenant only. betaOnly hid the tab on the production HOST, which is not the same as keeping the tool out of a production BUILD: the wholesale port to 315 took the files along, and every other host serving that build — a self-hosted instance most of all — showed the tab. Production 316 removes the tool from that build entirely, and here the tab, the palette entry and the data-tool link appear only when the signed-in tenant carries cloudfellows.dev, read from the organization's verified domains rather than from the signed-in account's own domain (a guest administrator carries their own). Demo mode is not that tenant, deliberately: this site is reachable by anyone. 25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. 0.6.1: folded into T08 Checks (build 25342) as the CIS 5.2.2 tab, hidden on the production host by the same isProdHost test the BETA ribbon uses — the carve-out in the promotion port is a tab guard now instead of a deleted file. The 17 recommendations, the four-tier outcome and the L1 and L2 filter are untouched;catalog r5: 5.2.2.6 user risk accepts Require risk remediation next to the password-change form — the newer control covers passwordless users and carries an authentication strength and sign-in frequency every time by itself, so those two criteria are implied by it; a tenant that moved to it no longer fails the control;catalog r4: disabled policies are evaluated too — a policy meeting every criterion while Off is its own ⏸ Configured tier (own chip, own count, not scored as pass: the benchmark audit requires state enabled, and the control says so), and a 5.2.2.5 strength that carries the phishing-resistant methods plus extras (PR + TAP) gets a 'close — remove the extras or document the deviation' message instead of a flat miss (after reviewing Jhope188's engine, which passes any admin auth-strength policy — deliberately not adopted);catalog r3: CAD- pilot deployment groups satisfy 'users: All' (include-group names resolved via Graph, noted on the control), the token-protection resource criterion names exactly which of the three apps is missing, sign-in-frequency misses show the interval actually found, and an unresolvable or too-broad authentication strength says so;in the tool tab bar; admin-scoped controls (5.2.2.1/.4/.5) accept an admin persona group (Admins / E-Admins token in the policy name + a group include) as the admin scope — with a note on the control, since the benchmark's Graph audit reads includeRoles; catalog r2: every-time sign-in frequency satisfies 5.2.2.13, a single grant control satisfies the OR-operator criterion on 5.2.2.9/.10;tool version shown in the header; the benchmark catalog (control set + assessment criteria, cisdata.js) carries its own revision stamp — 2026-08-10 — shown in the header and the Markdown report, so the CIS content is managed and released on its own track, separate from the app build and the other beta tools;BETA — the tenant's CA policies scored against the CIS Microsoft 365 Foundations Benchmark v7.0.0, section 5.2.2 Conditional Access: all 17 automated recommendations as per-control pass / report-only / fail with the exact Graph audit criteria per control, nearest-miss policies showing exactly which criteria they lack, L1/L2 profile filter, licence-awareness (the three Identity Protection controls drop to 'not licensed' when the tenant has no Entra ID P2), overall + per-level compliance score, Markdown compliance report. Recommendation numbers and titles referenced from the CIS Benchmark (© Center for Internet Security); assessment logic implemented from the benchmark's Graph audit procedures, full text not reproduced" },
  toolJson:         { t: 4, v: "1.3.1", folded: { into: "toolPolicies", build: 25338 }, note: "1.3.1: folded into T01 Policies (build 25338) — the tile is gone, the Backup action on the policy action bar is unchanged, runBackup and the baseline-tenant scoping untouched, and this Help section moved under Policies keeping its own name;1.3: on a baseline tenant the backup IS the baseline catalog — scoped to the persona CAxxx policies, with the dependencies read from those policies only, so nothing the tenant uses for itself can ride along; a warning states what is skipped, the zip is named ConditionalAccess-BASELINE-… and carries a BackupScope.json. No override.;policy zip including dependencies and terms-of-use PDFs" },
  toolProtect:      { t: 20, v: "3.0.4", head: "\ud83d\udd12 Protect exclusions", chips: ["UPDATED", "writes to tenant"], note: "3.0.4 (25386): under Joey Verlinden's baseline the groups every baseline shares have a vault — Emergency_Access1, Emergency_Access2 and CAB-SEC-U-BreakGlass go to CA-RMAU-BreakGlass, a CAD-SEC-U-DG deploy group to the unit of the persona its code names when his catalog has that persona; every one of them read unmapped before. 3.0.3: a lock that cannot be ticked says WHY on the tick — “no vault to put it in — map it, or pick a fallback unit”, “CAB-SEC-RMAU-INT-Exclusions does not exist yet — create it”, “blocked by 2 nested groups”, “state not returned by the directory” — instead of “see left”, and the row tick explains itself on hover. The baseline's own persona groups (CAB-SEC-U-Persona-Admins …) and deploy groups (CAD-SEC-U-DG-INT …) now resolve to their persona's vault by NAME — every one of them read “unmapped” before. A dynamic-membership group reads 🚫 never for nesting: its rule picks users or devices and a group can never be added, so there is nothing to disable and it no longer counts as missing that lock. 3.0.2: break-glass groups are on the list whatever references them. The candidate rule was “excluded by a policy”, and a break-glass account group — Emergency_Access1, BG-… — is INCLUDED by the break-glass policy and excluded by none, so it never appeared, even sitting in the BreakGlass vault. Any group named like a break-glass group that a policy includes is a candidate now, tagged break-glass, its Used by reading included by n. ⑥ inside CA groups follows. 3.0.1: nothing is ticked for you. 3.0 kept ⑥'s habit of pre-selecting every assigned exclusion group, which on a 115-group tenant read as Protect 83 under one visible tick. A tick is now something you did — a row, the header box, or the selection carried over from the groups list. 3.0: 3.0: TWO LOCKS PER GROUP. The restricted unit (who may change the members) and disableNesting (whether a group can be put inside) sit on one row, with a column each and a tick each — the ticks pre-set to what the row still lacks. Five tiles and chips say how far along the tenant is (fully protected, vault only, nesting only, open, cannot here); a row that cannot be protected says why on the row and carries the way out (⑦ Migrate, map the persona, empty the nested groups first). The AU / scoped-admin / acknowledgement prose folds into a Settings drawer. The run is the run ledger with both locks as steps, and the report has a Nesting column. Nesting is set in place (PATCH on v1.0, read back) and never by recreating; a directory that lacks the property gets one banner and “not reported” cells, and the nesting tick is off the table there. Same engines as ⑥ and ⑧ — ⑥ inside CA groups is unchanged. 2.1 (R36): routes groups into the active baseline's persona vaults; the fallback unit is named after that baseline's prefix;2.0: the standalone host of \u2465 Protect gains the same directory search as the tab \u2014 one renderer, so the panel, the refusals and the added-by-hand rows are identical in both places. See toolCaGroups 4.5; 1.9: a refused role-assignable row carries the way out on the row itself — a ⑦ Migrate it button that opens CA groups ⑦ Migrate (the conversion is not duplicated; ⑦ finds the group in its own scan), with a toast from the standalone tool saying to come back and protect it afterwards. A frozen row keeps no button, because its way out starts with leaving the unit, not with migrating. 1.8: the fallback administrative unit picker is styled like every other dropdown instead of a bare native control; 1.7 (R28): a group with no CA number in its name is routed to the vault THIS TENANT mapped it to \u2014 the row says \u201cmapped here\u201d when that is what decided it, and an unmapped group says so instead of being silently skipped;1.6: \u27f3 Re-check protection re-reads each group\u2019s administrative-unit membership and the AU list without leaving the tab or losing the selection; a group protected in the meantime drops out of the selection and its checkbox goes disabled. 1.5: select-all / deselect-all above the group list, counting only the rows that can actually be ticked, and the header no longer describes role-assignable groups as optional \u2014 they cannot be added at all, and it points at \u2466 Migrate. 1.4: role-assignable groups are refused, not merely left unticked \u2014 combining the two protections leaves nobody able to change the members (a role-assignable group admits only GA/PRA; a restricted AU blocks exactly those two, and neither can be assigned at AU scope). The checkbox is disabled, the row explains why, and the write itself filters them out in case a stale selection survives a rescan. 1.3: the scoped-administrator grant uses the same resilient directory-role resolution as Restricted AUs, so it no longer fails with a 400 \"conflicting object\" when the role is already activated but not listed. several scoped administrators, comma-separated, each resolved and granted on its own with per-account outcomes in the report;scan on demand (▶ button) instead of on open, result persists across tab switches until an explicit rescan, a scan in flight survives navigation; standalone view of the exclusion-group protection workflow — restricted management administrative unit (create if missing or reuse), per-group protection status, optional AU-scoped Groups Administrator, explicit acknowledgement, Markdown report; the same workflow remains available as CA groups ⑥ Protect" },
  toolCaGroups:     { t: 12, v: "5.14.1", note: "5.14.1 (25480, Mihai, screenshot: the policy count is off — used by 4, repoint 8?): BOTH NUMBERS WERE RIGHT AND READ AS ONE. Each group row counted the policies naming THAT group (the kept one: 4 include, 1 exclude); the foot counted the policies naming the group being RETIRED (7 + 1 = 8), which are the ones repointed. The row now reads named by N policies (x include · y exclude), the foot names the retired group's id beside the repoint count and says when a policy already names both (the duplicate reference is dropped), and a second line gives the total afterwards — the kept group's policies and the repointed ones, counted once. 5.14.0 (25477, Mihai: create merge for duplicate groups and remove one): 🔀 DUPLICATE NAMES. A toolbar button appears when two or more groups in the scan share one display name (the CloudFellows baseline had two CAB-SEC-U-Persona-Externals). The dialog reads each group's direct members, suggests the group to keep (most policies, then most members, then assigned over dynamic, and always one the merge can carry out), and plans per name: move the other group's missing members into the kept one, repoint every Conditional Access policy that names the other (include AND exclude, one PATCH of the whole users block, built from a FRESH read and read back), then rename the other aside as NAME (merged YYYY-MM-DD) — the default, found and deleted later by 🧹 Archived groups, which also checks uses outside CA — or delete it behind a typed DELETE. REFUSED, with the reason on the card: keeping a DYNAMIC group that lacks the other's members (a rule cannot be added to by hand), a policy that includes one and excludes the other (after the merge the exclusion would win), members that could not be read. Warned: a retired dynamic group with its own rule (whoever it adds tomorrow is no longer reached). THE ORDER IS THE SAFETY PROPERTY: members, then policies, and the other group is only touched when both landed — a stopped or refused run never removes a group a policy may still name. JSON backup of the groups, their members and every affected users block; run ledger; report. Pure module js/groupmerge.js with nine tests; ARCHIVE_SUFFIX and findArchived know the merged tag. 5.13.1 (25474, Mihai, screenshot: fix this bug in the layout): THE BOTTOM SHEET SLID UNDER THE RAIL. The Members / Compare sheet and the group action bar are position fixed and were laid out against the whole viewport; under the Workspaces shell the side rail (z-index 46, 88px) sits above them (43/44), so the sheet title, the Members tab and the add-member box lost their first 90px, and in full size the centred sheet reached the left edge. On a phone the sheet ran under the 62px bottom rail. css/workspaces.css now lays both out against the content area: left from the rail edge, centred on the space right of it, and above the bottom rail on a phone. Measured in Chromium on the demo: sheet left 3 → 98 at 1440 (rail ends at 88), bottom 844 → 782 at 390 (rail starts at 782). 25386: the groups every baseline shares count as the baseline's whichever catalog is active. With Joey Verlinden's active, Courseware listed the CAD-SEC-U-DG deploy groups its import had staged on and the E-Admins groups as not in the baseline; now the E-Admins groups (Emergency_Access1, Emergency_Access2, CAB-SEC-U-BreakGlass, and whatever an E-Admins policy includes) and any CAD-SEC-U-DG group are present, and the row says every baseline. Also counted: the name Joey's repository gives a group file (CA403-Guests), his example include group APP_Microsoft365_E5, and the exclusion group his naming rule gives a policy the tenant has under an older release name (CA005 AppEnforcedRestrictions). Under his catalog Baseline + templates expects the Emergency_Access pair and Create makes it from the CloudFellows template; deploy groups are never expected. The All groups scope classifies unreferenced groups the same way instead of listing all of them as not in the baseline. The other-baseline hint no longer counts the six shared E-Admins policies. Export MD says why a row counts. 25370: local result search suggestions; matching before the 60-option limit; no extra Graph requests. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. 5.11: T35 Teams devices is a ROW ACTION here instead of a tile. Create already makes CAB-SEC-U-TeamsSharedDevices as a dynamic group with the Teams rule, and T35 rebuilds that rule from the device licences the tenant actually holds — one action on one row, so it is offered where the group is (the Rule button on that row) and nowhere else, because on any other row it would mean nothing. Which row gets it is decided by TeamsDev's OWN alias list, the same one isAlias uses inside the tool, so a tenant that named the group CAB-SEC-U-SharedDevices still gets the action; a substring test is the fallback and the command palette reaches the tool either way. Nothing else in this tool changed;5.10: the drawer's Members tab has a FIND box and an order segment (as read / name / UPN). Typing filters the members read here — direct ones and the nested groups, which open by themselves on a match and drop out when nothing inside matches — and says how many match; every row keeps its ×. When the group is bigger than the 500 read, the count says so and a 🔎 button (or Enter) asks the tenant: the group's members matching the term, direct and transitive, placed under the nested group they came through (the children read here first, then checkMemberGroups), so the answer is either NOT A MEMBER or a row with a × that goes to the right group. A member under a DYNAMIC nested group no longer shows a × that would have failed against the parent. 5.9.9: 🧹 Archived groups says PARTLY DONE. A group taken out of 36 of 39 policies while 3 refused the change (the unpatchable REQ-PVM-ReqApp-* policies) read “refused” as if nothing had happened; the row is now amber ◐ partly done with both numbers — taken out of 36 of 39, still named by the three, not deleted so no policy points at nothing — the header and footer count partly done separately from failed, and the report has a Partly done table with the next step. The run ledger itself gained the state, so every batch write can use it. 5.9.8: ⑦ Migrate finishes the repoint past a refusal. The four passes (add the new group to the includes, to the excludes, remove the old from the includes, from the excludes) stopped at the first policy Graph refused, which left the old group in every policy of the later passes — seven archived originals still named by up to 46 policies. All four passes run now, the refusals are collected and named together, and what stays behind is exactly the policies that refused; the error says which and what to do (fix the policy, then 🎯 Assign). 5.9.7: an archived original a policy still names is called out. A “(migrated …)” group is the rollback a migration leaves behind, and one that policies still reference is a repoint that did not finish — the policy targets the old, frozen group. Such a row now says so under its name, is Needs attention, has its own 🧹 Archived, still in policies chip, and the drawer's Protection tab says what to do (🎯 Assign to swap the group, then 🧹). The Role-assignable chip counts within the list's scope — switch the scope to All groups to see every archived original, or use 🧹 Archived groups. 5.9.6: Used by names the BASELINE's policy number — CA002 from “CA002-BLOCK-…” — not ENCA's running number (CA068 = the 68th policy alphabetically), so the row no longer reads “CA002-Exclusion · excluded by CA068”; the drawer's Policies tab and the compare matrices follow. A policy whose name carries no CA number shows its full name. 5.9.5: the Empty chip is right from the first screen. The scan reads every group's direct-member count, and that answer arrives inside the batch as text the parser could not read — so every unread group stayed at not read and Empty counted only the groups whose members had been opened. 5.9.4: a finished migration unticks its groups. The ticks are by name and the new group takes the old name, so a migrated group stayed ticked through the re-scan and was carried into the next Migrate — where it showed under Not migrated as already a plain group. A completed Migrate or Archived-groups delete now drops its groups from the selection, and a tick on a name the scan no longer has is dropped on every render. 5.9.3: the 🚫 Nesting disabled chip finds them now. The list read disableNesting through a batch on the beta endpoint, and on a tenant where only v1.0 returns the property every group came back unknown — while the create had verified nesting disabled on the same groups through v1.0. The list reads through v1.0 too now, the route the create uses. 5.9.2: a refresh no longer pulls you back. The re-read after a policy write is asynchronous; when it finished it took the screen it had started from — so opening another tool while it ran ended with the groups list back in front of you. Now it checks whether you moved: if you did, it stays where you are and re-scans the list quietly, so it is current when you return. The same for every re-scan after a write inside the tool. 5.9.1: the ⑦ Migrate report says per new group whether NESTING is disabled — as the create verified it (read back), not as the tick asked: disabled, allowed (not requested), ALLOWED with the reason it could not be set, or not available in this tenant; a closing line points at the Protection tab when any new group still allows it. The step ledger in the dialog says the same. 5.9: 🚫 NESTING DISABLED is a chip. The list already read disableNesting per group after the scan and said nothing with it; now the chip counts the groups that have it set (the count fills in a moment after the list, a 0 is an answer), the members column carries 🚫 nesting disabled on those rows, and the drawer's Protection tab opens with the nesting state — disabled, allowed (with the ⑧ Disable nesting button right there), impossible on a role-assignable group, or not reported by a directory that lacks the property. 5.8.1: three things from a day on a real tenant. A refresh after a policy write (🎯 Assign from the drawer, the Compare → Policies ticks, a restore) brought you back to this list — it landed on 🗂 List Policies, because the re-read always did. 🧹 Archived groups counts the policy removals off as they go (taking it out of 112 policies… 10 of 112) instead of one line for two minutes. And the ⑥ Protect scoped-administrator box no longer reopens its list over a picked name. 5.8: every batch write shows the run ledger — the whole list before the first write, the row being written marked, ✓ or ✗ per row with the reason inline, the box scrolling to keep the working row in view, a count and a clock in the header, Stop between writes. ⑦ Migrate (one row per group, its steps as notes), 🧹 Archived groups, ⑥ Protect, ② Create, ⑤ Import CSV and the Compare → Policies ticks all use it; a dialog with failures stays open so the ✗ rows are read where they happened, and Create keeps its ledger until you close — the list re-reads the tenant then. The same box is in 🎯 Assign's Apply and 🎚 Set policy state. 5.7.2: the Archived groups delete is visible while it runs. It was working — the toasts were the only sign, and the dialog looked stuck for a minute with a greyed button. Now the dialog shows a progress bar and a step log (taking it out of n policies… ✓ verified · deleting… ✓ deleted), the title says Working… 2/6, and Close is locked until it is done. 5.7.1: the Archived groups Delete button re-evaluates on every tick, keystroke and re-render, says how many it will delete, and says why it is off (tick the groups / type DELETE) — it could stay off with DELETE typed and five rows ticked. 5.7: the list sorts. Click Group, Status, Members, Used by or Protection to sort by it, again to flip, a third time to go back to needs-attention first; the select-all box sits on the row's centre line like the others. 5.6.2: the Migrate step list names the restricted unit you chose — it kept naming the first unit in the tenant after the dropdown was changed. 5.6.1: a refused policy update says why. Four policies answered every add with a bare 400. Graph validates the WHOLE policy on any change, so a policy the portal saved with a setting the API no longer accepts refuses every update — including adding a group. On a 400 the policy is re-read and the known combinations are named (app-protection grant without an iOS/Android-only platform condition, Exchange ActiveSync mixed with other client types, the retired deviceStates, app-enforced restrictions off Office 365, the retired GuestsOrExternalUsers include), with the fix: open it in the portal, adjust, save, retry. The outcome stays above the grid instead of vanishing in a toast. The tick cells read as buttons — dashed until ticked, lemon when ticked. And every group write now carries the policy's guest / external-user block through, which a users PATCH used to drop. 5.6: the Policies view fixes what it finds. Every missing cell on a differing row is a tick — add this group to this policy the way the other group already is on it (+ex or +in); ☑ Tick every missing cell, then one button applies them, one policy update per tick, nothing removed; the grid updates in place. A row where the picked groups are named differently (one included, one excluded) shows ? instead — that needs a person. 5.5.3: the Compare sheet sizes itself to its content — as wide as the matrix needs (two groups do not earn the whole window) and as tall as the rows need, up to the tool area; the Half toggle stays. 5.5.2: the policy differences are said on the Members view too — a red callout naming what each group is missing, with a button to the Policies view — so the switch is not the only way to find them. 5.5.1: the 🧹 Archived groups dialog shows everything — as wide as the window allows, the table fitting it with wrapping cells, a group's policies as two names plus +n more with the full list on hover. 5.5: Compare compares POLICIES too. A Members | Policies switch in the sheet: Policies is a groups × policies grid — ● in, ✗ ex, · not named — with the rows where the picked groups differ first and marked, and a line per group saying how many inclusions and exclusions it is missing against the others. After a migration that is the list the new group still lacks; policy names open the card, 🎯 Assign fixes it. The member matrix is laid out like 🚪's: narrow group columns, the slack in a filler column, so two groups no longer stretch across the whole window. 5.4: a failed migration says where it stopped and where things stand. Each group carries a step ledger — rename aside, create, copy members, repoint, verify, place in the AU — with ✓ ✗ ⚠ per step, the failing step named in the tag, and a 'Where things stand' line saying what the tenant looks like now and how to finish or undo (a failed create rolls the rename back, so nothing changed; a failed member copy leaves every policy on the old group, so nobody is uncovered; a failed repoint says how many policies got the new group and how many lost the old one). And 🧹 Archived groups leaves nothing behind: a ticked group still named by a policy is taken OUT of those policies first (live read, removal, read-back) and deleted only when no policy names it; 🔗 Check other uses runs the User or Group analyzer's sources over the ticked groups — app assignments, Intune, licensing, Teams, admin units — and shows the hits per group before you delete. 5.3.4: Compare opens full height — the tool area below the header and the tabs — because a 79 × 2 matrix in half a window was not readable. ▁ Half in its header drops it to the half sheet where the list stays visible and the matrix follows your ticks; the choice is remembered. 5.3.3: the dialog covers the tool, not the app. It starts below the header and the tool tabs and no longer locks the page, so every other tool stays one click away while a migration runs — the tool keeps its own window in its own tab. And ⟳ Rescan inside Migrate re-checks the same groups with the same scope instead of throwing the list's scan away and checking all 94. 5.3.2: Empty counted only the groups whose members had been read, so the chip said 1 on a tenant with a dozen empty exclusion groups. The scan now counts every group's direct members ($count, in the same batch as the nested-group read), so Empty is right from the first screen, and an unread row shows its direct count next to the read button. And the word drift under the status is gone: it stood for 'role-assignable — migrate it', which the Protection column and the Role-assignable chip already say; the one drift that still shows is 'assigned, template is dynamic'. Role-assignable no longer counts as Needs attention — 66 of them drowned the dangling, unprotected and nested rows. 5.3.1: a row with 🔁 Restore and ⋯ overflowed the actions column and the status column broke 'present' in two. Column widths re-cut: status 84px, actions 150px, the buttons stacking on a narrow window; headers never wrap. 5.3: every action reviewed against a real tenant. (1) The drawer follows the tick: ticking a row opens it, unticking the open row opens the last one still ticked — the pane no longer shows a group you did not select. (2) The drawer's ＋ Add and × had lost their click handler when the list moved into its own element — restored. (3) ⋯ → Read members / Protect / Migrate / Import / Create now go the same way the bar goes: straight to the matrix or the scoped check for that one group, not the 133-group picker in a full-height sheet. (4) Compare shows the groups you picked, not every group read this session. (5) Migrate reuses the protection map the list already read (no memberOf call per candidate) and, on a tenant without Entra ID P2, treats the PIM eligibility read's licence error as 'no eligible roles' instead of skipping the group — a P1 tenant cannot hold eligible assignments. (6) The list fits its card: fixed column widths and wrapping cells, so the ⋯ column is never behind a sideways scroll. (7) The Compare sheet is sized to its content, up to 72% of the window. 5.2.1: the empty dialog on open. The dialog and sheet containers are flex boxes, and display:flex beat the hidden attribute — so an empty dialog covered the list the moment the tool opened. hidden wins now. 5.2: the actions never take the list away. An action from the bar used to swap the whole list for the engine screen, and Migrate's re-render after its scan wiped the ← Groups bar with it — you were in Migrate with nothing else on screen and no way back. Now the list stays put: the writes (Create, Assign, Import, Protect, Migrate) open in a DIALOG over the dimmed list — finish or close (✕ or Esc) and the ticks and the open row are exactly where you left them; ③ Compare opens as a SHEET rising from the actions bar, the bar becoming its header, and the list above stays live — tick more rows and the matrix follows. The actions bar itself is a real floating bar now, fixed to the bottom of the window. After a write the tool lands back on the list, not the old ① table. 5.1.3: Migrate from the list checks only the groups you came with. Each candidate costs three reads — directory roles, member count, restricted-AU membership — and the wizard was checking all 66 role-assignable groups for the one you clicked. Now it checks your selection, says so with a scoped tag, and offers the full check as a button. 5.1.2: the controls read as controls, in both themes. Filter chips: ink text, a firm border, lemon when on — the same lemon the primary buttons use; the three chips about a security exposure carry their colour even idle: Needs attention and Has nested groups red (a live bypass), Not protected amber (an unguarded one). The Members / Show nesting / Nested only switch in ③ Compare is a recessed track with a raised lemon key. Chips in 🌊 and 🛂 pick up the same base look. 5.1.1: the actions bar in dark mode was pale green with white text — unreadable. It now takes the deep green surface with a light border and light text, in both the chosen and the system dark theme. 5.1: first day on a real tenant. NESTING IN SIGHT — every scan now reads each group's nested groups (direct group members, one batch), so the ↪ Has nested groups chip is always there with a count before any member read, the members column and the drawer say which groups are nested, and a nested group inside an exclusion or break-glass group is Needs attention: whoever manages the nested group decides who bypasses the policy. ALL GROUPS scope: the third scope from the mockup — every security group in the tenant (first 5,000) next to the baseline's and the referenced ones, the extras listed as not in the baseline, their nesting and members read when opened. The actions bar shows as soon as a row is open, acting on that row until you tick more. Protect and Migrate reached from the list run their check straight away for the groups you came with instead of showing a Scan button for what you just clicked. The drawer sticks below the toolbar whatever height the chips wrap to, so its header stays in sight. 5.0: ONE READ, THEN EVERYTHING IS A ROW. The seven tabs — each starting its own scan, with “who is in CA011-Exclusion” three clicks and a 708 × 123 matrix away — are replaced as the way in by a single LIST of groups and a DETAIL DRAWER that follows the row you click. The list carries status, members (count, direct vs nested, read on demand), the policies that use the group with their state, and its protection, with filter chips for needs attention, missing, gone, empty, not protected, role-assignable, nested and not-in-baseline, sorted attention first; search matches members too. Tick rows for the actions bar: read members, compare selected (the old matrix, only for what you ticked), assign, protect, migrate, import CSV, create the missing ones. Each row offers what applies to it — Create on a missing group, Restore on a dangling reference, the wave on a deploy group, ⋯ for the rest. The drawer has four tabs: Members as a tree (direct members, then each nested group with its own members; add inline; × removes from the group the member actually sits in, nested included, asking first), Policies (include / exclude with state, names open the card), Protection (which restricted unit, or why it is not protected and the button that fixes it) and History (the group's last 30 days from the directory audit log, AuditLog.Read.All asked once). Nothing scans twice: the tenant read happens on open, members and nesting per group when first looked at, and a write re-reads only the group it touched. The seven engine screens still exist — create, compare, assign, import, protect, migrate — reached from the list with the selection carried across and a ← Groups button back. 4.9.1: the ③ Members matrix finally gets the grid every other matrix has. Since build 97 it was written with class names (tablewrap, stick, vert) that no stylesheet ever defined, so it rendered as bare rows with no card, no sticky header and no sticky first column — which the nesting view made impossible to ignore. It now uses the shared .matrix-wrap / .mtable grid of 🔍 Gap analyse and 🚪 Exclusion analyzer: card surface, vertical group headers with the member count in the tooltip, sticky Member column, scroll inside its own box, the In column at the end. 4.9: three things a 708 × 123 matrix asked for. HIDE EMPTY GROUPS — a checkbox next to the nesting segment drops the empty columns (63 of 123 on a baseline tenant, empty by design), and the wall of empty-group names becomes one line that opens on click. The label under a ◐ shows the TAIL of the nested group name, since nested groups share a long prefix and the tail is what tells them apart, with the full list in the tooltip; the nesting view also gives the cells room for it. A column whose every member came in through nesting carries ◐ in its header and says so in the tooltip — nothing in it is removable from this group. 4.8: ③ Members shows HOW as well as WHO. Every member read now also reads the group's direct list and its nested member groups (first 40, each with its own transitive users), so a Members / Show nesting / Nested only segment turns the matrix from ● into ● direct and ◐ through a nested group — the child group named under the dot and in the tooltip — and a NESTED GROUPS panel lists each nested group with its member count, its dynamic rule when it has one, and its members on click. The reason it matters is the write: a user in an exclusion group through SG-Finance-All cannot be removed from the exclusion group, only from SG-Finance-All, so a ◐ cell offers no ×, and the panel says where the − Remove has to happen. Best effort — a nesting read that fails leaves the flat matrix as it was and says nesting was not read. 4.7: ③ Members can REMOVE a member as well as add one. The bar is now ADD OR REMOVE A MEMBER with a − Remove button next to ＋ Add, and every ● in the matrix shows an × on hover. Both ask first, and the question says what the group is used for, because this is the one write in the matrix that can lock somebody out: taking a user out of an EXCLUSION group puts them back inside the policy, taking them out of an include group takes them out of its scope — the confirmation names the count of policies either way, and the success line says which policies the user is inside again. Dynamic groups are not offered (the rule decides), a user not read as a member is refused rather than deleted blind, and the group is re-read afterwards so the matrix shows the result. Needs Group.ReadWrite.All, asked on the click. 4.6.1: the ADD A MEMBER boxes get the app's input styling;4.6 (R36): ① Check and ② Create work against the ACTIVE baseline — Joey Verlinden's 38 groups when that is the choice — and the summary hints when the tenant looks deployed against the other one;4.5: \u2465 Protect and \u2466 Migrate reach ANY group in the tenant, not only what the scan found. One shared directory-search panel under both lists (js/app.js cgFindPanel / cgFindRun / cgFindAdd, kind protect or migrate): $search on displayName with a startswith fallback for tenants that refuse it, 25 hits, each tagged with what it is. An added group is checked like a scanned one \u2014 Protect reads its AU membership and routes it by persona, Migrate reads held directory roles, member count and restricted-unit membership \u2014 and is held in cgManual OUTSIDE cgRmau/cgMig so a rescan cannot drop it. The \uff0b Add button refuses what the tab cannot take (not role-assignable for \u2466, non-security or on-premises for \u2465) and the same guard runs at the write. FIXED alongside: an unreferenced group in \u2465 Protect had a disabled checkbox while the row said tick it deliberately \u2014 it is tickable now, still outside the pre-selection and \u2611 Select all. Clicking a group on \u2460 Check now opens its policies: the Included in / Excluded from names are pol-links to the policy card; 4.4: opening the tool now registers its tab no matter who opens it — the crumb moved off the home tile's click handler into openCaGroups itself, so the hand-offs that open this screen directly (⑦ Migrate it from Protect exclusions, the Restricted AUs cannot-list, the import preflight, the migration corner badge) get a Conditional Access groups tab beside the one you came from instead of the old tab staying active over the wrong screen. 4.3: \ud83d\udeab disable nesting is now OPT-IN on every create path and off by default \u2014 the property is not generally available (Microsoft documents the permission but publishes disableNesting on no group schema), so a tenant that lacks it refused the field and every create ended in a red failure line for a setting the panel had promised. The request goes to v1.0, the only version whose docs name it; a refusal is told apart from an ordinary failure, reported, and remembered for the session; and \u2467 Disable nesting no longer falls through to the destructive recreate when the property is unknown, because that route sets it at creation \u2014 the request that was just refused; 4.2 (R28): \u2465 Protect routes through CaMap.codeOf \u2014 this tenant\u2019s stated group \u2192 persona mapping first, the CA number second \u2014 so a tenant\u2019s own exclusion group reaches its persona vault without being renamed;4.1: \u2466 Migrate re-reads the policy references at repoint time and verifies the old group is gone; 4.0: \ud83e\uddf9 Archived groups gains select all / deselect all, ticking only what is safe to delete; 3.9: \u2466 Migrate survives navigating away \u2014 progress lives with the run and a corner badge shows it from any screen; deleting from a list keeps the scroll position; 3.8: the create panels stopped describing groups as role-assignable, which they have not been since 25026, and say what they now do instead; 3.7: the create result says whether nesting was disabled instead of applying it silently, and \u201cassigned\u201d is named as the membership type; every create path sets disableNesting and verifies it — in the create body and by PATCH, with the group never lost when the tenant refuses;3.5: clicking a group in \u2460 Check lists what you can do with THAT group and carries it across \u2014 only what applies is offered, so a missing group cannot have members read, a role-assignable one is offered \u2466 Migrate rather than \u2465 Protect, and a frozen group is told the unit must be left first. 3.4: same datalist fix on the \u2462 Members add bar \u2014 picking a user no longer reopens the suggestions. 3.3: role-assignable groups can no longer be CREATED \u2014 the builder offers assigned or dynamic with an optional restricted-AU placement instead, the \u21bb Recreate-role-assignable action is removed, and the \u2460 Check drift flag is inverted so a plain group is correct and a role-assignable one is what gets flagged (with a button into \u2466 Migrate). 3.2: the \u2462 Members add bar fills the group in when only one is loaded, keeps your last pick when it is still loaded, and clears it when it is not. 3.1: \u2462 Members gains an \u002b Add bar \u2014 directory type-ahead on the user, the loaded groups on the other side \u2014 and \u2466 Migrate keeps its options and Migrate button pinned to the bottom of the panel while you tick through a long list. 3.0: \u2466 Migrate no longer scans just because the tab was opened \u2014 a \u25b6 button starts it, like \u2465 Protect \u2014 and it is laid out in the same .cg-panel style as the rest of the tool instead of borrowing Drift watch\u2019s cards. 2.9: the \u2466 Migrate preview counts the members that will be copied, read the same way the copy reads them (direct members of every type), and says the archived group keeps its own copy \u2014 it is a copy, not a move, which is what makes the rollback real. 2.8: \u2466 Migrate gains select-all / deselect-all with a live count, and the restricted-AU placement is now optional \u2014 leave it off to convert in stages and place the groups later from \u2465 Protect, which the results screen offers as a button. 2.7: \u2466 Migrate (BETA) \u2014 move the baseline off role-assignable groups onto a restricted management administrative unit. Each group is recreated (isAssignableToRole is immutable): rename aside as \u201c(migrated YYYY-MM-DD)\u201d, create a plain group with nesting disabled, copy the members, repoint every policy, then place it in the restricted AU last. Groups holding a directory role, already in a restricted AU, or whose role check failed are skipped with the reason. Markdown report; the archived originals are the rollback. 2.6: the baseline catalog referenced CAB-SEC-U-CA1009-Exclusion (the CA1009 Azure DevOps block) with no matching group template, so the Check tab expected a group it could never offer to create — template added, and the catalog and template sets now reconcile exactly. recreate-as-role-assignable moves ALL member types across (users, service principals, devices — not just users), reports nested groups it cannot move (Entra forbids groups inside role-assignable groups), and the confirm dialog finally says the members come across — it still claimed the new group would be empty, a leftover from before build 219;🧹 Archived groups housekeeping (delete the leftovers a recreate renamed aside, with policy-reference and member guards); recreate now carries the members across; disable nesting hidden on role-assignable groups, which already forbid it;④ Assign targets directory roles as well as groups — include and exclude, with Microsoft’s 14-role privileged set as a quick pick;⑥ Protect takes several scoped administrators (comma-separated);🚫 Disable group nesting (BETA): Entra's beta disableNesting on a persona group so no group can be added as a member — three-state detection (disabled / allowed / not reported, since a plain read does not return it), the in-place PATCH attempted AND verified by reading the value back, rename + recreate + move user members + repoint policies only if Entra refuses and only behind a second typed confirmation, and a hard block when the group already contains nested groups;⑥ Protect: restricted management administrative unit for the CA exclusion groups — per-group protection status, create/reuse the restricted AU (isMemberManagementRestricted, immutable), optional AU-scoped Groups Administrator, explicit acknowledgement, Markdown report; ⑤ Import members: bulk-add pilot users from a CSV (UPN + optional multi-persona column) with persona→group auto-mapping, membership pre-check, review-before-apply and a Markdown change report;baseline group check, creation, members × groups matrix, and policy assignment in one tool, per-group member scan, manual group builder, remove-group action, final confirm, assignment change report, pick-by-persona, TeamsSharedDevices template, per-row create, recreate-role-assignable, convert-to-dynamic (in place or rename + recreate + reassign)" },
  toolAuthCtx:      { t: 22, v: "1.1.1", head: "\ud83c\udfab Authentication contexts", chips: ["writes to tenant"], folded: { into: "toolLocations", build: 25341 }, note: "25408: the results list and the detail pane each scroll on their own, pinned under this screen's toolbar. 25406: Shared list/detail workspace with native actions and flat icons. 25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25370: local result search suggestions; matching before the 60-option limit; no extra Graph requests. 1.0.1: folded into T15 Policy building blocks (build 25341) as the Contexts tab; usedBy delegates to CaUses. The slot accounting, the publish state and the create path are untouched;out of BETA — manage the Conditional Access authentication contexts (c1-c99): list every defined context with publish state and the CA policies that enforce it, create in a free slot, rename, edit the description, publish / unpublish with one click, delete guarded by Graph's own rules (unpublished + unreferenced only, typed confirmation), free-slot count, Markdown export, demo mode. The id is treated as the immutable contract it is" },
  toolAuthStr:      { t: 23, v: "1.1.1", head: "\ud83d\udcaa Authentication strengths", chips: ["writes to tenant"], folded: { into: "toolLocations", build: 25341 }, note: "25408: the results list and the detail pane each scroll on their own, pinned under this screen's toolbar. 25406: Shared list/detail workspace with native actions and flat icons. 25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25370: local result search suggestions; matching before the 60-option limit; no extra Graph requests. 1.0.2: folded into T15 Policy building blocks (build 25341) as the Strengths tab; usedBy delegates to CaUses, including the case-insensitive id compare the delete guard depends on. Built-in versus custom, the combinations and the phishing-resistant class are untouched;1.0.1: the AAGUID box gets the app's input styling;Out of BETA as of production 294 \u2014 already 1.0, and the chip was the only thing still calling it unproven; 1.0: in production. BETA — 0.2: Advanced options as in the portal — restrict Passkeys (FIDO2) to specific AAGUIDs (Microsoft Authenticator / Windows Hello presets or any custom AAGUID) and certificate-based authentication to specific issuer SKIs and policy OIDs, read via $expand, written via combinationConfigurations (create carries them inline; edit diffs POST/PATCH/DELETE); restrictions shown on the cards and in the Markdown report. manage the Conditional Access authentication strengths: the three built-in strengths read-only with their combinations, custom strengths created / renamed / re-combined (via Graph's dedicated updateAllowedCombinations action) / deleted when no policy grants them (typed confirmation), each strength classified phishing-resistant / MFA / allows-single-factor by its weakest combination, per-strength policy usage, combination picker grouped by class with the live catalog read from Graph (curated fallback), Markdown export, demo mode" },
  toolTou:          { t: 25, v: "1.1.1", head: "\ud83d\udcdc Terms of use", chips: ["BETA", "writes to tenant"], folded: { into: "toolLocations", build: 25341 }, note: "25408: the results list and the detail pane each scroll on their own, pinned under this screen's toolbar. 25406: Shared list/detail workspace with native actions and flat icons. 25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25370: local result search suggestions; matching before the 60-option limit; no extra Graph requests. 1.0.1: folded into T15 Policy building blocks (build 25341) as the Terms of use tab; usedBy delegates to CaUses. The per-device acceptance, the re-accept frequency, the file list and the delete guard are untouched;1.0: in production. PDFs actually load: the list endpoint never returns fileData, so each agreement is now fetched individually with $expand=files — languages and the ⭳ PDF download appear on the cards, and the edit dialog lists the current PDFs (language, default marker, view/download); create fixed: the POST carries only what the create API accepts (name, view-before-accepting, files) with per-device and re-accept applied in a follow-up PATCH, and Save now awaits the file reader so a fast Save cannot race the PDF upload;BETA — manage the terms-of-use agreements Conditional Access can require: every agreement with its behaviour settings (view-before-accepting, per-device acceptance, re-accept schedule, expiration), its PDFs per language with direct download, and the policies requiring it; create with a PDF upload (base64 inline per the Graph contract), edit the behaviour settings, per-agreement acceptance summary on demand (accepted / declined counts + latest, AgreementAcceptance.Read.All requested only then), delete blocked while any policy requires the agreement (dangling-grant protection) and typed-confirmed; Markdown export, demo mode. PDF replacement / extra languages deliberately not yet in scope" },
  toolRmau:         { t: 27, v: "1.8.4", head: "\ud83d\udee1 Restricted AUs", chips: ["writes to tenant"], note: "25370: local result search suggestions; matching before the 60-option limit; no extra Graph requests. 1.8.3: the baseline's persona groups (CAB-SEC-U-Persona-NAME) and deploy groups (CAD-SEC-U-DG-CODE) resolve to their persona by name, so ＋ Bulk add offers them for the right unit and 🏷 Group personas no longer lists them as unmapped. 1.8.2: the persona chips and ＋ Bulk add no longer offer ARCHIVED groups. After a ⑦ Migrate the renamed-aside original — “Emergency_Access1 (migrated 2026-09-10)” — still matches the break-glass name prefix, so the unit card listed it under cannot, role-assignable, with a Migrate button, while the real Emergency_Access1 was already a member. Archived originals are rollbacks, not candidates; they are dropped from both scans. 1.8.1: the Group personas name box gets the app's input styling;1.8 (R36): the persona units, ＋ Bulk add, the persona chips and the fallback name follow the active baseline; the R28 group mapping is kept per baseline because the codes differ;1.7 (R28): \ud83c\udff7 Group personas \u2014 a per-tenant mapping from a group to the persona vault it belongs in, so a group with no CA number in its name reaches a vault without being renamed. Exact match on object id or display name only, never inferred; the mapping wins over the CA number and every row says which rule decided; the unmapped are listed rather than dropped. Held in the browser under the tenant id, with JSON export/import;1.6: the baseline checklist stopped printing a Scoped admin column it never read — every pre-existing unit showed an em dash, which alongside a footnote about vaults nobody can open documented a tenant with four scoped Groups Administrators as having none. The column is gone and the report states what it does and does not cover; a grant made while creating a unit is still reported, on the row it belongs to;1.5: the persona group suggestions carry the protection check — what cannot be added is listed with the reason rather than offered as a click that fails, and the chips come from a tenant scan rather than from baseline names;1.4: the per-unit scoped-admin field really does take several people — the type-ahead searches the entry being typed instead of the whole string, and each person is a separate grant with its own outcome;1.3: the bulk scoped-administrator grant is searchable — find people by name, pasted lists still work, both feed one list;1.2: adding a group offers this unit's persona groups first, one click each, with manual entry for any other group — the same shape as granting a scoped administrator;1.1: \ud83d\udc64 Grant scoped administrators across units is findable \u2014 its own panel above the unit cards and a toolbar button, rather than a line of small print at the foot of the baseline checklist; it no longer depends on the baseline panel, so it works on a tenant whose units are not the baseline's. 1.0: in production — persona vaults, bulk add, bulk scoped-admin grants, frozen-group detection, and out of BETA. 0.8: on an AU card the add-member and grant-admin pickers sit ABOVE their lists — a protected AU can hold dozens of groups, and with the list first the input was pushed off the bottom of the card. 0.7: picking a suggestion no longer reopens the dropdown \u2014 selecting from a datalist fires the same input event as typing, so the pick re-ran the query and the browser reopened the list over a field you had already filled. 0.6: the help states the role-assignable/restricted-AU deadlock explicitly. 0.5: a removed member or scoped grant stayed on the card. The code did re-read after the write — but Entra directory writes are not read-your-writes consistent, so the DELETE returns 204 and the very next GET still lists the object, and the re-read faithfully restored the row. Changes are now applied to the card immediately and confirmed against the directory with backoff (3 tries over ~4s); if the directory has not caught up the card keeps showing what you did rather than resurrecting a deleted row, and says so. Adds get the same treatment in the other direction, and both input boxes clear once the entry is on the list. 0.4: granting a scoped administrator failed with a 400 \"conflicting object\" on tenants where the directory role exists but GET /directoryRoles does not return it — the code then tried to activate a role that was already there. Role resolution is now a ladder (alternate-key GET, $filter, activate, unfiltered list matched client-side) and a conflict is treated as evidence the role exists, not as a failure. Granting someone who already holds the role says so instead of relaying Graph's wording. 0.3: 👤 Scoped admins now lands on the grant box and focuses it, with a brief highlight — on an already-expanded card it scrolled to the button that had just been pressed, which looked like a dead button. 0.2: each card carries a 👤 Scoped admins button (with the current count) opening the panel where roles are granted — it was only reachable by clicking the card header, so people looked under ✎ Edit, which is a PATCH of the AU's own name and description; the Edit dialog now points at it. The add-member box suggests the baseline group names before you type (those are what the AU exists to protect) and folds in live directory results for any other group or user; the scoped-administrator box suggests users from Entra as you type. BETA, beta-site only — manage restricted management administrative units: list every AU (restricted first) with members and scoped role grants, per-member CA-reference badges (which policies include/exclude a protected group), add and remove members (group by name, user by UPN), grant and revoke scoped directory roles (Groups/User/Helpdesk/License Administrator via the activated-role + scopedRoleMembers pattern), edit name and description, create (restricted flag set at creation — immutable, and the tool says so) and delete with typed confirmation, Markdown export. The management face of the ⑥ Protect flow's vaults." },
  toolRecycle:      { t: 24, v: "1.1.1", head: "\u267b Recycle bin", chips: ["writes to tenant"], folded: { into: "toolLocations", build: 25341 }, note: "25408: the results list and the detail pane each scroll on their own, pinned under this screen's toolbar. 25406: Shared list/detail workspace with native actions and flat icons. 25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25370: local result search suggestions; matching before the 60-option limit; no extra Graph requests. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. 1.0.1: folded into T15 Policy building blocks (build 25341) as the Deleted tab. It is in that tool rather than in Policies because the 30-day restore window holds deleted named LOCATIONS as well as deleted policies. The restore path is untouched;out of BETA — the Conditional Access recycle bin: recently deleted policies AND named locations (both share the 30-day soft-delete window), each with what it did, its state at deletion, when it went and how many days it has left; expiring-soon filter; one-click restore with the right guard rails — a policy that was On at deletion enforces again the moment it is restored, so that restore demands a typed RESTORE, name collisions with the live set are flagged, and restoring a trusted location warns that All-trusted policies follow it again immediately; the live policy set reloads after a policy restore so every other tool sees it; Markdown export, demo mode" },
  toolDevCheck:     { t: 30, v: "1.1.3", head: "\ud83d\udda5 Compliant-device reality check", chips: ["NEW"], folded: { into: "toolGapCheck", build: 25342 }, note: "25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. 1.1.1: folded into T08 Checks (build 25342) as the Intune reality tab. The four verdicts, the per-platform grid and the Intune reads are untouched, and the Intune scopes are still asked for on the run and not on opening the tool;1.1: the toolbar carried a second \u25b6 Check the coverage next to the big one in the run prompt, and before the first run the two did exactly the same thing. The toolbar button is now \u27f3 Rescan and appears only once there is a result to redo \u2014 the Change audit shape, as in \ud83c\udfab Licence gap. A refused consent or a failed Intune read now offers Try again in the panel, which it has to: with the toolbar button hidden there was otherwise no way to run the tool again without leaving and reopening it; 1.0: in production and out of BETA — the compliant-device reality check (roadmap R11). Per Conditional Access policy and per platform, proves whether require-compliant-device scope is covered by an Intune compliance policy, reads the tenant default for devices with no assigned policy, checks app protection behind require-approved-client-app, names OR alternatives, and exports Markdown. Assignment targets are re-read when list expansion omits them; direct assignment is checked first, then transitive group memberships are matched when names alone cannot prove overlap. Unreadable, unenumerable and over-cap scopes remain honestly not proven. Read-only; requests DeviceManagementConfiguration.Read.All and DeviceManagementApps.Read.All on the click" },
  toolGuide:        { t: 29, v: "0.3.3", head: "\ud83d\udcd6 Baseline usage guide", chips: ["BETA"], folded: { into: "toolBaseline", build: 25340 }, note: "25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. 0.3.1: folded into T10 Baseline (build 25340) as the Deployment guide tab, beta-only. The six steps, the tenant readiness checks and the export are untouched; openGuide is unchanged;0.3 (R36): the readiness checks read the active baseline's groups, units and policies, and the header says when the step prose was written for the other one;0.2: policy readiness names every missing CA policy instead of showing only persona totals, and uses the Baseline tool's number-clash-safe matcher so unrelated policies cannot fill the count;BETA, beta-site only — the baseline usage guide (roadmap R05): the deployment order as six steps, each with the REASON it sits there rather than just the sequence — the persona model and its CA ranges read from the catalog, groups and their restricted-AU vaults before the policies that make them worth attacking, named locations / authentication strengths / contexts before the policies that reference them by id, Terms of use before import (the one dependency with no create API), policies imported Off on purpose, then Off → report-only → 🎚 forecast → enforced with Global last. 🔎 Read the tenant turns every step into a readiness check — n of m baseline groups, n of m restricted units, trusted-location flag, published contexts, agreements (Agreement.Read.All asked on the click; declined reads as 'not read', never a fake empty), per-persona policy coverage against the 99-policy catalog and the Off / report-only / enforced tally — with the missing items named BEFORE the step is run instead of after. Every step links the tool that does the work; reads only, nothing written; Markdown readiness report; demo mode" },
  toolUserImpact:   { t: 32, v: "1.2", head: "\ud83d\udde3 User impact brief", note: "1.2: tied to the baseline it depends on. These rules match on POLICY SHAPE and the bundled catalog (T10 \ud83e\uddec Baseline Policies) decides what shape a requirement is written in \u2014 revision 2026-08-20 moved CA205 and CA301 from a grant to a block and the brief silently stopped covering them. The rules now carry the revision they were last checked against; when the loaded catalog is newer the brief says so on screen AND in both exports, and js/baselineData.js tells whoever bumps the revision to walk the rules first; 1.1: the company-device requirement was only recognised as a GRANT, so every policy expressing it the other way \u2014 a BLOCK on everything that is NOT joined, via a device filter \u2014 was left out of the brief entirely (CA205, CA301, CA309 in the bundled baseline). Entra has no grant control for require Entra joined, only compliantDevice and domainJoinedDevice, which is why the baseline writes it as a block. Both forms now land in one item, the text names whichever consequences apply, and domainJoinedDevice (hybrid join) is recognised as a grant for the first time; 1.0: in production and out of BETA, with \u27f3 Re-read & analyse (queue item 84) shipping alongside; 0.4: \u27f3 Re-read & analyse. The brief is DERIVED from the policy set already in memory rather than read for itself, so it was exactly as current as whenever the tenant was last loaded \u2014 and nothing on the screen said when that was. The header now states it (just now, 5 min ago, 3 d ago) and the button re-reads the tenant and rebuilds the brief, returning to this tool rather than dropping you on the policy list. Always present: this tool has no first run to distinguish it from, so there is nothing to gate it behind; 0.3: opening it adds a tab, like every other tool. Its crumb name and its tab-registry label disagreed by one word, so the match failed silently: no tab was pushed and the home button stayed lit while you were standing on the tool;0.2: the persona baseline (CAxxx-numbered policies) is analyzed FIRST and carries the brief; everything without a persona CA number — a tenant's own or interim policies — is analyzed last, in its own trailing section on screen and in both exports, so a temporary policy can never lead the communication. Same persona rule Backup and the Gap checks use;BETA — the rollout communication written by the tenant itself: what people will notice and what will deliberately no longer be possible, derived from the Conditional Access policies actually deployed. 23 detection rules translate policy configuration into end-user language (MFA, phishing-resistant strengths, legacy-auth and device-code blocks, app protection, app-enforced restrictions, session lifetimes, persistent browser, country allowlists, compliant network, compliant device, unknown platforms, guest allowlists, admin O365 blocks, risk remediation and blocks, insider risk, terms of use, guarded registration, Azure DevOps lockdown), each statement grouped per audience (persona token first, assignment shape as fallback; service accounts, workload identities and break-glass deliberately excluded), stamped live now / staged / at go-live from the policy states, and backed by the named policies with click-through to the policy card. Audience filter, 'no longer possible' short list, Markdown export via the report viewer and a text-based Word (.docx) export built client-side. Reads only what is already in memory — no Graph calls of its own" },
  toolDrift:        { t: 28, v: "1.0.3", head: "\ud83d\udcc9 Drift watch", folded: { into: "toolAudit", build: 25340 }, note: "25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. 1.0.1: folded into T16 Changes (build 25340) as the Snapshot file tab. The snapshot, the compare, the severity ranking and the export are untouched; openDrift is unchanged and keeps its callers;1.0: in production and out of BETA — now snapshots the restricted administrative units too. 0.3: an area that could not be compared says WHICH SIDE failed — a snapshot taken before a read was fixed keeps carrying that failure, and reporting it in red as though it were happening now is misleading; a stale-snapshot area is now marked as such, in muted type, with the fix (take a fresh snapshot) stated, while a genuine failure in the current run stays red. When both sides failed, both reasons are given instead of only the snapshot's. 0.2: cards carry their own padding (the shared .list-card leaves spacing to whatever it wraps, which for every other tool is a table — bare prose sat flush against the border); authentication strengths falls back to a plain read when the tenant rejects $expand with a 400, and if the two snapshots captured different field sets the area says so instead of reporting the missing fields as drift somebody caused. BETA — configuration drift against a snapshot file you keep, so it has no 30-day limit (the Change audit log does). Snapshots policies, named locations, authentication strengths and authentication contexts; a later run reports added / removed / changed with a field-level diff, ranked by severity — a widened exclusion, a policy switched Off or a location turned trusted outrank a rename, because that is how protection disappears quietly. GUIDs resolve to names, volatile fields (modifiedDateTime) are ignored so an untouched policy reads as unchanged, an area that failed to read is reported as not captured rather than as clean, and if the Change audit tool has already run, each drifted object names who changed it. Markdown report. No server, nothing uploaded" },
  toolLicGap:       { t: 31, v: "1.2.0", head: "\ud83c\udfab Licence gap", folded: { into: "toolAnalyze", build: 25348 }, note: "25412: results are bound to the run that made them (js/runmeta.js). A strip above every result states tenant, policy snapshot time, policy states, population, completeness and a run id; a policy reload, tenant change or sign-out DROPS the results computed from the previous snapshot instead of leaving them on screen under a new tenant, and the strip turns amber if the snapshot moves under a result. 25411 (1.1.0): three measures, never one. Estimated demand (targeted identities), seats PURCHASED and entitlement ASSIGNED to those identities are separate numbers with separate actions — the bar drew purchased capacity and labelled it “targeted users licensed”, so a green bar could sit above a named list of unlicensed users. Purchasing shortfall and assignment remediation are stated apart. One eligible population for numerator and denominator: exclusion sets are intersected with the member users before being subtracted from a member count, so an excluded guest can no longer take a member out of scope (a one-member tenant excluding one guest reported 0 in scope and 1 gap user). A zero gap over an incomplete read says NO GAP FOUND IN THE RESOLVED SCOPE, never that everyone is licensed. Mailbox states report what was read: a denied read is MAILBOX READ DENIED with a verify-in-Exchange pointer, a returned userPurpose is named as such with the feature-dependent licence note, and no mailbox classification recommends dropping Conditional Access. The tab states its population, and insider risk counts as P2 in both tabs. 25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25370: local result search suggestions; matching before the 60-option limit; no extra Graph requests. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. 1.0.2: folded into T03 Gap analyse (build 25348) as the Licences tab. The obligation read, the per-user verdicts, the ways to close the gap and the export are untouched; openLicGap is unchanged and keeps its callers;1.0.1: the admin-groups box — picking a suggestion from the search box no longer reopens the list over the filled field — choosing from the list fires the same input event as typing, so the pick re-ran the search and the browser reopened the dropdown. 1.0: in production and out of BETA. A tool a customer can open is not a 0.x thing \u2014 whatever it accumulated on the beta channel, the BETA chip was what said still proving itself, and that has come off; 0.13: a failed tenant read left no way to retry \u2014 the toolbar Rescan is hidden until there is a result, and the error panel replaced the run prompt, so the tool became unrunnable without reopening it. The error now carries Try again. Introduced with the Rescan pattern in 25164; 0.12: the user read can be FINISHED on a big tenant - the per-pass cap rose to ~50k and a Read-the-remaining-users button continues the read from its saved nextLink (same per-user rules via one shared mapper, bounded per click, re-analyzed in place), because on a 32k tenant the exact gap tile next to a prefix-only named list read as two numbers disagreeing; the partial chip now says first N of M users read instead of just capped. 0.11: one run button - the toolbar duplicate of Count the gap became Rescan and appears only once a result exists to redo (the Change audit pattern); the first run belongs to the big button in the prompt. 0.10: a count on the card is one click from its rows — the breakdown chips are clickable and open the pop-out pre-filtered to that bucket, the pop-out gains a Category column and filter buttons whose counts mirror the card exactly (one shared classifier decides the bucket, so the numbers cannot disagree), and the not-classifiable pill says outright that those identities are not rows in the list. 0.9: role members are resolved by TYPE — a role held through a role-assignable group is expanded to the group’s transitive users (previously the group object counted as one opaque id and its members silently did not), service principals holding a role are ignored because they hold no user licences, and a failed group expansion marks only that role’s count approximate. 0.8: gap users holding NO licences of any kind are labelled (chip, pop-out tag, export) — usually service accounts or sync artifacts that never consume Microsoft services, so the to-license count stops being inflated by accounts nobody would buy for; adopted from office365itpros’ target-set argument after comparing our approach against Tony Redmond’s Get-UnlicensedEntraP1Users.PS1 (whose remaining differences — report-only ignored, scoped-policy exclusions not subtracted, suspended SKUs counted as owned, assignedPlans-based licence check, P1 only — we deliberately do not adopt). 0.7: the tile’s gap and the named list use ONE definition of licensed — per-user licensing now comes from assignedLicenses matched against the same live SKU set the seat totals count (per-user disabledPlans respected), not from assignedPlans, which keeps plans in grace from suspended subscriptions and made the list read smaller than the tile by exactly those users; users whose only P1/P2 is such a grace plan are IN the gap and labelled ‘in grace — seat no longer owned’ (chip, modal tag, export); targeted identities with no member-user record (guests via groups, over-cap) are counted as ‘not classifiable’ instead of silently dropped. 0.6: several admin-accounts groups can be excluded at once — picked one after another from the same auto-fill field, each shown as its own chip with its own ✕, the UNION of their transitive user members excluded (one merge point, so counts and lists cannot disagree), the result and export naming every group. 0.5: an admin-accounts group can be excluded from the scan — Microsoft licenses people, and a second internal account of an already-licensed person needs no second licence; the picker auto-fills with the groups the loaded CA policies reference and searches the directory live from two characters, the group’s transitive user members drop out of every count and named list (intersected with the member-user list where it is complete, so guests in the group cannot undercount the obligation), the exclusion is re-applied without re-reading the tenant, and the result and export state the exclusion with the document-the-mapping caveat. 0.4: the mailbox check WORKS on a normal tenant — a delegated token can only read another mailbox’s settings when the signed-in person holds rights on it, so the direct userPurpose read fails almost everywhere; but the failure itself answers the question: gap users are unlicensed, a regular unlicensed user has NO mailbox, so ‘access denied’ means a mailbox EXISTS without a licence (likely shared/room/equipment, labelled as such with a verify-in-Exchange note) while ‘mailbox not enabled / not found’ means a plain unlicensed account; \ responses now carry the Graph error code so the two can be told apart, the check button counts what it will check against its cap, and live progress runs on the button. 0.3: per-policy Gap column — how many users each policy targets without the licence it needs assigned, so the row that drags unlicensed users in is visible at a glance; the named gap moved into a searchable pop-out (a large tenant makes the list hundreds of rows; the card now shows the decision breakdown — to license / disabled-cleanup / shared-resource — with View all opening the dialog), and 🏷 Check mailbox types reads each gap user’s mailboxSettings.userPurpose on demand (MailboxSettings.Read, asked once, gap users only, capped and batched) to label shared / room / equipment mailbox accounts as never licensed — disable or exclude, not buy; the labels carry into the Markdown export, and an unreadable mailbox stays ‘not readable’ rather than passing as a user. 0.2: the gap is NAMED, not just counted — the member users are read with their assigned service plans, and every targeted user without a P1 (or, for risk policies, P2) licence assigned is listed by UPN on screen and in the Markdown export, disabled accounts flagged as cleanup candidates rather than purchases, with the unassigned-seat count bridging seats-owned and seats-assigned; the P2 half is always shown, saying explicitly when no active risk policy creates an obligation (and which disabled ones would); a capped user read marks the lists partial instead of pretending to be the whole tenant. BETA — Licence gap: targeted users versus P1/P2 entitlements. The licence usage blade counts evaluated users (who triggered a policy last month); the obligation is on targeted users. Resolves the actual targeting of every active policy — All-users minus exclusions, or the union of included users, transitive group members and directory-role holders minus exclusions — and compares the cross-policy union with the P1/P2 seats owned, matched on the AAD_PREMIUM / AAD_PREMIUM_P2 service plans so bundles count and suspended subscriptions do not. Risk-based policies create the P2 obligation; report-only counts, disabled does not (but a disabled risk policy is named as a P2 obligation waiting to happen); unreadable or over-cap scopes are marked approximate rather than presented as exact; guests deliberately not counted. Explains why the gap exists and the ways to close it, with trade-offs. Reads only, no extra consent. After Rudy Mens' Get-EntraLicenseGap.ps1 (lazyadmin.nl)" },
  toolTeamsDev:     { t: 35, v: "0.4.2", head: "\ud83d\udcde Teams devices", chips: ["BETA", "writes to tenant"], folded: { into: "toolCaGroups", build: 25349 }, note: "25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. 0.4.1: folded into T12 Conditional Access groups (build 25349) as the Rule action on the TeamsSharedDevices row. The licence read, the rule derivation (device-only plans, never MCOEV or TEAMS1), the preview and the write are untouched; openTeamsDev is unchanged, carries the host's crumb now, and its screen has a Groups button back to the list it came from;0.4: ROLLBACK. Before the PATCH, a JSON file with the group as it is — rule, processing state, group types, and the members of an assigned group — plus the exact PATCH (and PowerShell) that restores it is downloaded; a ⎌ Roll back button after the write restores it in the same session. The user-suite markers now prefer the SharePoint plans whenever the tenant's suites carry them and derive a plan only for a suite they do not cover — a derived plan that sits in every suite could be one admins disable per user. 0.3: the people holding a device licence on their own account are a TABLE — account, UPN, every licence on it with the device SKUs marked, enabled or disabled — up to 100 rows, on screen and in the Markdown, instead of a run-on line of names. 0.2: the rule gets a NOT half — an account that also holds a user suite (E1/E3/E5, F1/F3, A3/A5, Business) is a person and stays out, whatever device licence sits on it; the suite markers are derived from the tenant's SKUs (smallest set covering every suite, SharePoint plans as the static fallback), the preview applies the same NOT, and the people holding a device licence on their own account are counted and named. 0.1: new. Reads the tenant's subscribed SKUs and keeps the service plans that exist ONLY in Teams device licences (Rooms, Teams Shared Space, Phone resource accounts) — the plans a dynamic rule can use without pulling E5 users in — builds the membership rule from them, previews how many accounts it matches today, grades every group that looks like a Teams group (current, update, matches PEOPLE, assigned), lists the active policies that still reach the devices with a control from Microsoft's not-supported table, and replaces the rule on the group after a confirmation. UPN prefixes cover the accounts no plan can isolate. Teams Phone Standard is a user licence and stays out." },
  toolLocations:    { t: 15, v: "1.10.0", head: "\ud83c\udf10 Named locations", chips: ["writes to tenant"], note: "1.10.0 (25437): THE SIXTH TAB — \ud83c\udfd7 Policy builder (T41), the policy the other five tabs are blocks of; every block pane gains New policy with this location / strength / context / terms, which opens the builder with that step pre-filled;25408: the results list and the detail pane each scroll on their own, pinned under this screen's toolbar. 25406: Shared list/detail workspace with native actions and flat icons. 25371: workspace tabs resume the last subtab; browser history restores the tool and subtab. 25370: local result search suggestions; matching before the 60-option limit; no extra Graph requests. 1.8: THE HOST of the four kinds of object a policy references. T22 Authentication contexts, T23 Authentication strengths, T25 Terms of use and T24 Recycle bin are folded in as tabs and the tile is Policy building blocks. The four were four copies of one screen — a list, which policies use each row, create / edit / delete — and carried four private copies of the same query, one per module; those are now one implementation in js/causes.js (CaUses.by(kind, id, raws)), with each tool keeping its usedBy as a one-line delegation so no call site moved. The All-trusted-locations case this tool knew about — a policy that never names a location but reaches it through All trusted locations, so it changes behaviour the moment the trusted flag is flipped — is the shape the shared lookup carries, and every kind gets a normalised side field. The Deleted tab is here rather than in Policies because the restore window holds deleted named LOCATIONS as well as deleted policies;1.7: the broad-range finding NAMES the prefix to narrow to, per range and per address family — /24 for an office and /16 at the widest for a corporate estate, /48 for an IPv6 site and /64 for a single network — and the explanation states only the family that actually fired, instead of opening an IPv6 finding by explaining what a /8 is.;1.6 (R37): four findings over what the tool already read \u2014 dangling policy references, empty country locations, overly broad IP ranges, and untrusted IP locations where policies rely on All trusted locations; panel above the list, \u26a0 badge per row, in the per-location report and first in the Markdown export. No extra Graph call. The untrusted check is silent where nothing consumes All trusted locations and where a Block policy or the name itself says the location is untrusted on purpose;1.5: a country location is built by typing the COUNTRY, not the two-letter code \u2014 249 ISO 3166-1 entries with the code and name on a chip, paste normalised in place, and anything that is not a real code named rather than dropped (UK and EU are not codes; the United Kingdom is GB). named locations inventory with policy usage; create/edit/delete IP-range and country locations, CIDR + ISO-code validation, trusted-flag impact warning, typed confirm when a referenced location is deleted, card grid + table view, per-location report with full policy usage, per-location and inventory Markdown, JSON config snapshot + compare — out of BETA" },
  toolState:        { t: 5, v: "1.0.1", folded: { into: "toolPolicies", build: 25338 }, note: "1.0.1: folded into T01 Policies (build 25338) — the tile is gone, the Policy state action on the bar and the per-card quick action are unchanged, and openStateModal with its run ledger is the same dialog;On / report-only / Off switching" },
  toolImport:       { t: 6, v: "2.13.3", note: "2.13.3 (25483, Mihai's Perfetti import report of 23 Sep: 10 replaced, 8 failed): CREATED BUT NOT YET VISIBLE IS NOT A FAILURE YET. All eight failures were the same thing — the policy was created (id given), then Conditional Access answered does not exist for the whole ~20 s read-back, so activation and the switch-over of the old version never ran; the new version stayed Off beside the old one On, and a re-run skips it by name, so it could not be finished by importing again. The half after the create is now its own function (afterCreate: verify, activate, switch the replaced version Off). A policy that is still unread after the first wait is parked (onItem phase pending, the ledger row stays open with a note) and the run carries on; at the END of the run every parked policy is checked again with a longer wait (2+4+8+15+30 s, opts.lateWaits in tests) and finished exactly as it would have been. Only a policy still invisible after both checks fails, and says so, with the way to finish it. Two tests in tools/import-joey.test.cjs, one covering the switch-over of the replaced version on the second check. 25385: reads after a write are repeated with a backoff — Conditional Access answered 404 to the read that followed each E-Admins create on Courseware and all six were reported as failed although they had been created; a policy still unreadable after about 20 seconds is reported as created but not verified, with its id. Dependencies are matched to the chosen policies as whole values: the authentication context c3 was created because a GUID in the E-Admins files contained c3. The groups the E-Admins policies name are filed in the break-glass unit, and an E-Admins policy no longer brings a deploy persona group along in Deployment groups mode. 25384: agent policies are written in the create shape Graph documents, not the read shape an export carries — Graph refused all five of Joey's CA5xx files as written (a bare 400, Courseware). Agent identities lose the users None block and the empty service-principal list; agents' user accounts are written as users AllAgentIdUsers instead of the agents object; OData annotations are left out; the undocumented agent execution environment is retried without, once, and the report says the policy then covers every session; an agent filter or users plus agents in one policy is refused with the reason. The Workload ID licence warning shows only for a file that has workload-identity policies. 25383: groups are attached BY NAME. The group ids in a file belong to the tenant it was exported from; every reference becomes the group's name, the group is created or found by that name, and the policy gets this tenant's id. A group that cannot be created holds back the policies that name it instead of letting them land on an id this tenant does not have (a Joey import had left 34 such references, the break-glass group among them). One source id under two names (Joey's CA005 and CA006) gives each policy the group carrying its own name; a policy's own exclusion group under another name (CA403, CA404) is created under the name the convention gives the policy; a backup restored into its own tenant binds to the same objects; a user, group or named location id no file explains must exist here. New mode As shipped, the default for a baseline that is not CloudFellows. Re-attach: policies already in the tenant that point at the file's source ids get the named groups swapped in and are read back. E-Admins: taken into any import from a CloudFellows backup ZIP or folder, break-glass group renamed to the target baseline's, landing Off. The readback no longer compares OData annotations (every Joey policy was reported as differing after it had been created), null preview properties are not sent, the compliant network location is referenced by its fixed id instead of being created as an IP location, agent policies carry a preview tag and a failure hint, and UTF-16 zip and folder files decode. 25368: trustworthy read coverage, P1 preflight and responsive execution; see the build validation report. Fail closed on missing exclusions and app references; stage disabled, read back, restore approved state, verify before superseding. Accurate state and partial failure reporting. 2.10: the import shows the run ledger — the same box every other write shows — instead of a toast per policy behind the dialog. Row 0 is the dependency pass (groups, locations, strengths, contexts, terms of use; created or reused, with the count), then one row per policy: created / updated in place / switched, the old version switched Off, unknown app references dropped, or ✗ with the reason inline. Stop between policies. A clean run closes the dialog; one with a refusal stays open so the ✗ rows are read where they happened, and the report opens either way. 2.9 (R36.1): 🔀 Switch baseline — a third assignment mode: policies land with the baseline's own groups as shipped (created here), the members of the other baseline's counterpart groups (break-glass, same-CA-number exclusion, persona include) are COPIED across before the policies land, a superseded same-policy-other-name is switched Off, and the report lists every copy; offered when the file matches a baseline the tenant is not on, pre-selected when its policies visibly use the other baseline's groups. The plan now recognises an unversioned baseline (same CA number + same name = present; a same-number policy whose name contradicts is never replaced in place), and an Agents persona whose include stays as shipped. A live repository read imports directly, no zip;2.8: the \u267b\ufe0f preflight no longer selects disableNesting in the batch that finds a file's groups \u2014 a tenant without the property answered the whole sub-request with a 400, which read as \u201cnone of these groups exist here\u201d rather than as a failure; nesting is read on its own pass, and the harden ticks write to v1.0; 2.7 (R28): a reused group is filed into the vault THIS TENANT says it belongs in \u2014 group routing goes through CaMap.codeOf (tenant mapping first, CA number second) instead of the CA number alone, so a group like Contractors-NoMFA no longer falls through to persona inference;2.6 (R04): the preflight no longer just NAMES what a reused group is missing \u2014 each reusable row carries a tick for what is still open on it (disable nesting, file it into its persona vault), anything impossible says why on the row instead of offering a dead checkbox, nothing is pre-ticked, and the writes run after the policies import so a failed import leaves every existing group as it found it; membership is never touched and every outcome, failures included, reaches the change report; 2.5: a tenant that partly has the groups is spelled out \u2014 what a reused group inherits, and what it does not; the preflight finds the role-assignable groups a file would build on and hands the conversion to \u2466 Migrate (R04); match & replace: an unmappable terms-of-use / custom auth-strength id falls back to the ids of the policy being replaced (they are tenant-valid by definition) instead of failing the upgrade with a bare 400; failed updates now say explicitly that the current policy is untouched;dependencies first, persona remapping, placeholder resolution, change report, on-screen report, claims-challenge step-up, up-front consent, import by persona, dependency scoping to selection, terms-of-use checklist, assignment mode (deployment groups or match & replace: keep the current policy's assignment and switch its superseded version Off), Workload ID licence check (workload-identity policies held back when the tenant lacks the SKU), retry without app references the tenant cannot resolve" },
};

// ======================================================================
// THE HEAD LINE. One tool, one title, one place (build 25352).
//
// Every tool screen opens with an h3 naming the tool, its chips and its
// permanent number. That line used to be typed into the tool's renderer
// once per STATE — reading, failed, loaded — which is how seven tools
// ended up saying different things about themselves depending on what
// they were doing. 🎫 Authentication contexts, 💪 Authentication
// strengths, 🌐 Named locations, ♻ Recycle bin and 🛡 Restricted AUs all
// dropped their "writes to tenant" chip while they were reading and got
// it back when they finished; ⚡ CA validator's NEW chip did the same;
// 📜 Terms of use had three different title lines. A warning chip that
// disappears while a tool is working is worse than no chip: it is there
// when you are looking at the result and gone when you are deciding
// whether to press the button.
//
// The chips describe the TOOL, not the state its head is in, so they
// live here beside the number and the version, and toolHead() is the
// only thing that writes the line.
//
// This also retires HEAD_TOOL — a hand-kept map of 33 head element ids
// to tool ids, with a MutationObserver on each one re-stamping the
// version every time a tool re-rendered its own head. The stamp is part
// of the line now, so there is nothing to observe and nothing to keep
// in step. The two heads written as static HTML in index.html (🔍 Gap
// analyse's intro and 🔒 Protect exclusions) are stamped once at
// startup, because they never re-render.
//
// A chip is named by its text; the class comes from this table, so a
// "writes to tenant" chip cannot be red on one screen and grey on the
// next. Pass an object for a chip that needs its own tooltip.
// ======================================================================
// A tool's permanent number, derived from the registry's own t field. This
// lived in app.js's closure until build 25352, where toolHeadTail() — which
// runs from version.js, before app.js — could not reach it.
const toolNo = (t) => (t && t.t) ? `T${String(t.t).padStart(2, "0")}` : "";
const HEAD_CHIP = {
  "NEW": "new", "BETA": "new", "UPDATED": "upd",
  "writes to tenant": "block", "writes": "block",
  "reads only": "ok", "READ ONLY": "ok",
};
// version.js loads before app.js, so it cannot borrow app.js's esc().
function headEsc(v) {
  return String(v == null ? "" : v)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}
function headChip(c) {
  const txt = typeof c === "string" ? c : (c && c.txt) || "";
  const cls = (typeof c === "object" && c && c.cls) || HEAD_CHIP[txt] || "";
  const ttl = (typeof c === "object" && c && c.title) ? ` title="${headEsc(c.title)}"` : "";
  return `<span class="tag${cls ? ` ${cls}` : ""}"${ttl}>${txt}</span>`;
}
// The chips and the number, without the h3 — for the two tools whose title
// is built from data rather than named here: 🧬 Baseline names its catalog
// and release, 👥 CA groups names the tenant.
function toolHeadTail(toolId) {
  const t = (typeof TOOL_VERSIONS !== "undefined" && TOOL_VERSIONS[toolId]) || null;
  if (!t) return "";
  const chips = (t.chips || []).map(headChip).join(" ");
  const no = toolNo(t);
  const stamp = t.v
    ? `<span class="tool-ver-head" title="${headEsc(`${no ? `${no} — this tool's permanent number. It never changes and is never reused, so it means one thing across both channels, every build and any future language.\n\n` : ""}${t.note || ""}`.trim())}">${no}${no ? " · " : ""}v${headEsc(t.v)}</span>`
    : "";
  return `${chips ? ` ${chips}` : ""}${stamp}`;
}
// The whole line. opts.title overrides the registry title (a tool whose
// title is built from data); the markup of both is trusted, because both
// are written here rather than read from a tenant.
function toolHeadInner(toolId, opts) {
  const o = opts || {};
  const t = (typeof TOOL_VERSIONS !== "undefined" && TOOL_VERSIONS[toolId]) || {};
  const title = o.title != null ? o.title : (t.head || "");
  return `${title}${toolHeadTail(toolId)}`;
}
function toolHead(toolId, opts) {
  return `<h3>${toolHeadInner(toolId, opts)}</h3>`;
}
